const n=[{id:4501,lesson:26,level:"N4",title:"～んです / ～んですか",formula:"V / Aい / Aな / N + んです",meaning:"Giải thích lý do, nguyên nhân hoặc xác nhận thông tin (văn nói)",usage:["1. Cấu trúc chia:","• Động từ thể thường (Vる/Vない/Vた) + んです","• Tính từ đuôi -i + んです","• Tính từ đuôi -na + な + んです","• Danh từ + な + んです","2. Trong câu hỏi 「～んですか」: dùng xác nhận thông tin nghe/thấy hoặc tò mò hỏi nguyên do.","3. Trong câu trần thuật 「～んです」: dùng giải thích lý do, nguyên nhân cho câu hỏi."],notes:["Đôi khi ～んですか biểu thị sự ngạc nhiên hay tò mò. Tuy nhiên nên dùng lịch sự để tránh thất lễ."],examples:[{ja:"どこで 買ったんですか。",romaji:"Dokode kattandesuka.",vi:"Anh mua ở đâu vậy?"},{ja:"…日本で 買いました。",romaji:"…Nihonde kaimashita.",vi:"Tôi mua ở Nhật Bản."},{ja:"どうして 遅れたんですか。",romaji:"Doushite okuretandesuka.",vi:"Tại sao anh lại đến muộn?"},{ja:"…バスが 来なかったんです。",romaji:"…Basu ga konakatandesu.",vi:"Tại vì xe buýt không đến."}]},{id:4502,lesson:26,level:"N4",title:"～んですが、～",formula:"～んですが、Vていただけませんか / Vたらいいですか",meaning:"Đưa ra chủ đề ngập ngừng, nhờ vả lịch sự hoặc xin lời khuyên",usage:["～んですが thường dùng để mở đầu chủ đề một cách lịch sự, theo sau là lời nhờ vả hoặc xin ý kiến.","1. ～んですが、Vていただけませんか: Xin hãy làm giúp tôi (rất lịch sự)","2. ～んですが、Vたらいいですか: Tôi nên làm thế nào thì tốt?"],notes:["ていただけませんか lịch sự hơn てください."],examples:[{ja:"日本語で 手紙を 書いたんですが、見て いただけませんか。",romaji:"Nihongo de tegami wo kaitandesuga, mite itadakemasenka.",vi:"Tôi đã viết thư bằng tiếng Nhật, anh xem giúp tôi được không?"},{ja:"コピー機の 使い方が 分からないんですが、 chỉ dẫn してもらえませんか。",romaji:"Kopiiki no tsukaikata ga wakaranai ndesuga...",vi:"Tôi không biết cách dùng máy photo, anh chỉ giúp tôi được không?"}]},{id:4503,lesson:27,level:"N4",title:"Động từ thể khả năng (可能形)",formula:"V-える / V-られる / できます",meaning:"Có thể làm gì (diễn tả khả năng, năng lực)",usage:["1. Cách chia thể khả năng:","• Nhóm 1: Chuyển âm cuối hàng -i sang hàng -e (Ví dụ: いきます -> いけます, かきます -> かけます).","• Nhóm 2: Thêm られる vào sau thân động từ (Ví dụ: たべます -> たべられます).","• Nhóm 3: します -> できます, きます -> こられます.","2. Trợ từ を chuyển thành が: [N が V thể khả năng]."],notes:["Tất cả động từ thể khả năng sau khi chia đều trở thành động từ nhóm 2."],examples:[{ja:"日本語が 話せます。",romaji:"Nihongo ga hanasemasu.",vi:"Tôi có thể nói tiếng Nhật."},{ja:"一人で 病院へ 行けますか。",romaji:"Hitori de byouin he ikemasuka.",vi:"Bạn có thể đi bệnh viện một mình được không?"}]},{id:4504,lesson:27,level:"N4",title:"Cách chia",meaning:"thể hiện khả năng, năng lực làm việc gì đó (Những động từ khi được biến đổi sang thể",usage:["Nhóm I: Là các động từ có vần [ i ] đứng trước ます。Để chuyển sang động từ thể khả năng chỉ cần","chuyển [ i ] thành [ e ].","～ ます 可能形（かのうけい）","およぎ ます およげ ます","よみ ます よめ ます","いき ます いけ ます","はしり ます はしれ ます","うたい ます うたえ ます","もち ます もて ます","なおし ます なおせ ます","Nhóm II: Bỏ ます thêm られます","たべ ます たべられ ます","おぼえ ます おぼえられ ます","たて ます たてられ ます","Nhóm III:","します  できます","きます  こられます"],notes:["tất cả các động từ sau khi chuyển sang thể khả năng đều trở thành động từ nhóm II","＊ Chú ý: Trong câu, trợ từ [を] được chuyển thành [が], Các trợ từ khác vẫn giữ nguyên."],examples:[{ja:"Cách chia",romaji:"Cách chia",vi:"thể hiện khả năng, năng lực làm việc gì đó (Những động từ khi được biến đổi sang thể"}]},{id:4505,lesson:27,level:"N4",title:"私は 日本語 を 話します。Tôi nói tiếng Nhật",meaning:"私は 日本語 を 話します。Tôi nói tiếng Nhật",usage:[" 私は 日本語 が 話せます。Tôi có thể nói tiếng Nhật","FPT University Tiếng Nhật cơ sở 3","ひとり びょういん い"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"私は 日本語 を 話します。Tôi nói tiếng Nhật",romaji:"私wa 日本語 o 話shimasu。Tôi nói tiếng Nhật",vi:"私は 日本語 を 話します。Tôi nói tiếng Nhật"}]},{id:4506,lesson:27,level:"N4",title:"～しか ～ません",formula:"N + しか + V-ません",meaning:"Chỉ N (luôn đi với động từ thể phủ định)",usage:["1. しか mang nghĩa 'chỉ', nhấn mạnh sự ít ỏi hay giới hạn.","2. しか luôn đi kèm với động từ dạng phủ định (～ません).","3. Phân biệt: [dale] đi với câu khẳng định, còn [しか] đi với câu phủ định."],notes:["しか thay thế cho các trợ từ が, を khi đứng sau danh từ."],examples:[{ja:"ひらがなしか 書けません。",romaji:"Hiragana shika kakemasen.",vi:"Tôi chỉ có thể viết được chữ Hiragana."},{ja:"500円しか ありません。",romaji:"Gohyaku en shika arimasen.",vi:"Tôi chỉ có 500 Yên."}]},{id:4507,lesson:28,level:"N4",title:"V１ます ＋ ながら、 V２ (cách diễn đạt 2 hành động xảy ra",meaning:"vừa (làm 1) vừa (làm 2)",usage:["đồng thời)","hành động thứ 2 là hành động chính, được nhấn mạnh hơn."],notes:["Mẫu câu này không chỉ diễn tả 2 hành động xảy ra trong 1 thời gian ngắn mà còn diễn tả","2 hành động xảy ra đồng thời, liên tục trong 1 thời gian dài.","Hành động mang tính chất thói quen trong quá khứ thì được biểu thị bởi「V ていました」"],examples:[{ja:"彼は テレビを",romaji:"彼wa テレビo",vi:"飲みながら"},{ja:"学生の時、アルバイトをしながら",romaji:"学生no時、アルバイトoshinagara",vi:"大学で"},{ja:"V ています。",romaji:"V teimasu。",vi:"(động từ dạng tiếp diễn diễn tả 1 thói quen,"},{ja:"Ở bài này, gần giống như ý nghĩa trên, 「V ています」dùng để diễn tả 1 thói quen, 1 hành động có",romaji:"Ở bài này, gần giống như ý nghĩa trên, V teimasudùng để diễn tả 1 thói quen, 1 hành động có",vi:"tính chất lặp đi lặp lại nhiều lần trong cuộc sống sinh hoạt hàng ngày."},{ja:"休みの日は",romaji:"休mino日wa",vi:"スポーツを しています。Ngày nghỉ tôi hay/thường chơi thể thao."},{ja:"夜は いつも",romaji:"夜wa itsumo",vi:"日本語を"},{ja:"ひまな時、友達と",romaji:"himana時、友達to",vi:"話したり、本を"},{ja:"子供の時、毎晩 8時に",romaji:"子供no時、毎晩 8時ni",vi:"寝ていました。Hồi còn bé tối nào tôi cũng vào lúc 8 giờ."}]},{id:4508,lesson:28,level:"N4",title:"Thể thường し、Thể thường し、～",meaning:"vừa thế này, lại thế kia nữa; vì thế này, và vì thế này nên…",usage:["Động từ V る･V ない･V た","Tính từ đuôi i ～い","dạng","Tính từ đuôi na","ngắn ～だ し","Danh từ","～だ","し được dùng để liệt kê các nội dung khác nhau của một đề tài hoặc trình bày nhiều hơn một","nguyên nhân, lý do (có thể nhiều hơn 2, nhưng thường chỉ liệt kê 2)"],notes:["trong mẫu câu này, ta dùng trợ từ「も 」 để thay thế cho trợ từ「が」hay「を」với hàm ý","nhấn mạnh vào các lý do đưa ra","a) ～し、～し、（それに）～ vừa …vừa… hơn nữa","Có thể dùng mẫu câu này để miêu tả những nội dung khác nhau của một đề tài."],examples:[{ja:"(1) ミラーさんは",romaji:"(1) ミラーsanwa",vi:"親切だし、 頭 もいいし、それに ハンサムです。"},{ja:"(2) ミラーさんは",romaji:"(2) ミラーsanwa",vi:"ビアノも 弾けるし、ダンスも できるし、それに 歌も 歌えます。"},{ja:"(1) きょうは",romaji:"(1) kiょuwa",vi:"雨だし、お金もないし、（それで） 出かけません。"},{ja:"(2) この店は",romaji:"(2) kono店wa",vi:"食べb物も おいしいし、値段も 安いし、（それで） 人が 多いです。"},{ja:"どうして この会社に 入ったんですか。",romaji:"doushite kono会社ni 入っtandesuka。",vi:"Tại sao bạn lại vào công ty này làm việc?"},{ja:"残 業 も ないし、ボーナスも 多いですから。",romaji:"残 業 mo naishi、ボーナスmo 多idesukara。",vi:"Vì không phải làm thêm giờ, và tiền thưởng lại nhiều."}]},{id:4509,lesson:29,level:"N4",title:"Bài 29 - Điểm ngữ pháp chính",meaning:"Bài 29 - Điểm ngữ pháp chính",usage:["(ý nghĩa mới, cách dùng mới của"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 29 - Điểm ngữ pháp chính",romaji:"Bài 29 - Điểm ngữ pháp chính",vi:"Bài 29 - Điểm ngữ pháp chính"}]},{id:4510,lesson:29,level:"N4",title:"V ています động từ dạng tiếp diễn  diễn tả trạng thái)",meaning:"V ています động từ dạng tiếp diễn  diễn tả trạng thái)",usage:["Mẫu câu này được dùng để diễn tả trạng thái của sự vật diễn ra ngay trước mắt và kết quả của nó hiện","vẫn còn như thế. Các động từ dùng trong mẫu câu này là tự động từ, tức là các động từ chỉ trạng thái","và hầu hết là diễn tả các hành động tức thời.","Cũng với ý nghĩa này, chúng ta đã học 「結婚しています」「住んでいます」「知っています」","「持っています」(bài 15) nhưng những biểu hiện này có chủ thể là con người. Bài này, chúng ta học","cách thể hiện với chủ thể là những đồ vật mà chúng ta nhìn thấy.","1.1 N が V ています (câu thể hiện trạng thái của đồ vật)","Thể hiện trạng thái của đồ vật sau khi xảy ra 1 việc gì đó và hiện giờ (thời điểm nói) kết quả của","việc đó vẫn còn tồn tại và người nói nhìn thấy được."],notes:"Khi diễn tả trạng thái xảy ra trong quá khứ, chúng ta dùng V ていました",examples:[{ja:"まどが 閉まっています。Cửa sổ đóng",romaji:"madoga 閉maっteimasu。Cửa sổ đóng",vi:"( cửa sổ đang trong trạng thái đóng, có thể là do gió hoặc ai đó làm nó đóng lại)"},{ja:"いすが 壊れています。Cái ghế bị hỏng",romaji:"isuga 壊reteimasu。Cái ghế bị hỏng",vi:"( cái ghế đang trong trạng thái hỏng, có thể là do ai đó làm hỏng)"},{ja:"ふくろが 破れています。Cái túi bị rách",romaji:"fukuroga 破reteimasu。Cái túi bị rách",vi:"( cái túi đang trong trạng thái rách, có thể là do vướng vào đâu đó hoặc ai đó làm rách)"},{ja:"窓のガラスが",romaji:"窓noガラスga",vi:"割れていますから、危ないです。Kính cửa sổ bị vỡ nên rất nguy hiểm."},{ja:"Khi muốn đưa 1 sự vật, sự việc nào đó làm chủ đề của câu nói thì thay trợ từ「が」 bằng 「は」.",romaji:"Khi muốn đưa 1 sự vật, sự việc nào đó làm chủ đề của câu nói thì thay trợ từga bằng wa.",vi:"Ví dụ minh họa"},{ja:"Với cách nói này người ta thường sử dụng các đại từ chỉ định như「この」「その」「あの」 để",romaji:"Với cách nói này người ta thường sử dụng các đại từ chỉ định nhưkonosonoano để",vi:"chỉ rõ chủ thể được nhắc đến."},{ja:"その皿は",romaji:"sono皿wa",vi:"割れています。Cái đĩa đó thì vỡ rồi"},{ja:"あの皿は",romaji:"ano皿wa",vi:"汚れていますから、洗ってください。Cái đĩa kia thì bẩn quá, đem đi rửa đi."}]},{id:4511,lesson:29,level:"N4",title:"V てしまいます",meaning:"(làm gì) mất rồi",usage:["2.1. V てしまいました／V ていしまいます (diễn tả sự hoàn thành, hoàn tất","1 hành động)","a) V ていしまいました : Đã hoàn thành; Đã xong (1 hành động trong quá khứ)","Mẫu câu này dùng để nhấn mạnh sự hoàn thành thật sự của hành động. Vì vậy đứng trước nó","thường là các trạng từ như もう、ぜんぶ","trong một tình huống xấu."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"宿 題は",romaji:"宿 題wa",vi:"もう"},{ja:"お酒を",romaji:"o酒o",vi:"全部 飲んでしまいました。Tôi đã uống hết rượu rồi."},{ja:"b) V ていしまいます : Sẽ hoàn thành, sẽ xong (1 hành động trong tương lai)",romaji:"b) V teishimaimasu : Sẽ hoàn thành, sẽ xong (1 hành động trong tương lai)",vi:"Mẫu câu này dùng để diễn tả sự hoàn thành của hành động trong tương lai."},{ja:"明日までに",romaji:"明日madeni",vi:"レポートを"},{ja:"パスポートを 無くしてしまいました。Tôi làm mất hộ chiếu mất rồi.",romaji:"パスポートo 無kushiteshimaimashita。Tôi làm mất hộ chiếu mất rồi.",vi:"Ví dụ minh họa"},{ja:"電車に",romaji:"電車ni",vi:"かばんを"},{ja:"スーパーで",romaji:"スーパーde",vi:"財布を"}]},{id:4512,lesson:30,level:"N4",title:"V てあります (diễn tả trạng thái, kết quả hành động với",meaning:"Mẫu câu「～てあります」dùng để diễn tả trạng thái của sự vật như là kết quả của hành",usage:["tha động từ)","Để diễn tả sự tồn tại của đồ vật hay người nào đó, ta đã học cách nói với 「います」「あります」","Để diễn tả tình trạng, trạng thái hiện thời của đồ vật, ta có 2 cách nói:","「～ています」 đã học ở bài trước","「～てあります」 bài này học","(diễn tả trạng thái, kết quả hành động:","1.1. N１ に N２ が V てあります ở đâu có … cái gì)","Thể hiện trạng thái của đồ vật sau khi xảy ra 1 việc gì đó và hiện giờ (thời điểm nói) kết quả của","việc đó vẫn còn tồn tại và người nói nhìn thấy được. Trong đó, đặt trọng tâm ý muốn nói ở hành","động và mục đích thực hiện hành động đó."],notes:["ần phân biệt sự khác nhau giữa V てあります và V ています","「V てあります」 ： Các động từ dùng trong mẫu câu này là tha động từ","「 V ています」 ： Các động từ dùng trong mẫu câu này là tự động từ"],examples:[{ja:"壁に 地図が",romaji:"壁ni 地図ga",vi:"はってあります。Trên tường có dán bản đồ."},{ja:"教 室に",romaji:"教 室ni",vi:"テレビが"},{ja:"これは 私 の本です。名前が書いてありますから。Đây là quyển sách của tôi. Vì có ghi tên mà.",romaji:"korewa 私 no本desu。名前ga書itearimasukara。Đây là quyển sách của tôi. Vì có ghi tên mà.",vi:" (hàm ý là tôi đã ghi tên mình vào quyển sách nhằm mục đích không lẫn với của người"},{ja:"N２は N１に V てあります",romaji:"N２wa N１ni V tearimasu",vi:"cái gì thì… ở đâu)"},{ja:"(1)",romaji:"(1)",vi:"A：地図は"},{ja:"B：地図は",romaji:"B：地図wa",vi:"壁に"},{ja:"(2)",romaji:"(2)",vi:"パスポートは"},{ja:"① 窓が",romaji:"① 窓ga",vi:"閉まっています。Cửa sổ (đang) đóng."},{ja:"② 窓が",romaji:"② 窓ga",vi:"閉めてあります。Cửa sổ (đang) được đóng."}]},{id:4513,lesson:30,level:"N4",title:"V ておきます (1 mẫu câu mới với động từ dạng -te)",meaning:"(1) (làm gì) trước (để chuẩn bị);",usage:["2.1. （～まえに）、～V ておきます","Diễn tả 1 hành động cần làm trước để chuẩn bị cho 1 hành động khác xảy ra"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"旅行の まえに、切符を 買っておきます。Trước khi đi du lịch tôi sẽ mua vé trước.",romaji:"旅行no maeni、切符o 買っteokimasu。Trước khi đi du lịch tôi sẽ mua vé trước.",vi:"Ví dụ minh họa"},{ja:"パーティの まえに、部屋を 掃除しておきます。Trước bước tiệc, tôi sẽ dọn dẹp phòng trước.",romaji:"パーティno maeni、部屋o 掃除shiteokimasu。Trước bước tiệc, tôi sẽ dọn dẹp phòng trước.",vi:"Ví dụ minh họa"},{ja:"パーティの まえに、 料 理を",romaji:"パーティno maeni、 料 理o",vi:"作っておいたほうがいいです。"},{ja:"授 業 が 終わったら、電気を 消しておきます。Khi kết thúc giờ học thì sẽ tắt điện.",romaji:"授 業 ga 終waっtara、電気o 消shiteokimasu。Khi kết thúc giờ học thì sẽ tắt điện.",vi:"Ví dụ minh họa"},{ja:"パーティーが 終わったら、部屋を",romaji:"パーティーga 終waっtara、部屋o",vi:"片付けておきます。Khi bữa tiệc kết thúc thì sẽ dọn phòng."},{ja:"練 習 が 終わったら、道具を",romaji:"練 習 ga 終waっtara、道具o",vi:"元の 所 に"},{ja:"(1)",romaji:"(1)",vi:"まだ"},{ja:"(2)",romaji:"(2)",vi:"A：テレビを消してもいいですか。"},{ja:"B：もうすぐ ニュースの 時間ですから、つけておいてください。",romaji:"B：mousugu ニュースno 時間desukara、tsuketeoitekudasai。",vi:"Vì sắp đến giờ thời sự rồi nên cứ để bật như thế."}]},{id:4514,lesson:30,level:"N4",title:"まだ V ています／V ていません (cách diễn đạt 1 hành động vấn đang tiếp diễn",meaning:"vẫn đang… / vẫn chưa…",usage:["hoặc chưa hoàn thành)","còn diễn đạt ý vẫn chưa hoàn thành tại thời điểm hiện tại thì dùng câu phủ định"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"まだ 雨が",romaji:"mada 雨ga",vi:"降っています。Trời vẫn đang mưa."},{ja:"まだ 漢字を",romaji:"mada 漢字o",vi:"覚えていません。Tôi vẫn chưa nhớ được chữ Hán."},{ja:"た なか",romaji:"ta naka",vi:"き"},{ja:"田中さんは",romaji:"田中sanwa",vi:"まだ"}]},{id:4515,lesson:31,level:"N4",title:"Động từ thể ý chí (意向形)",formula:"V-おう / V-よう / しよう / こよう",meaning:"Cùng làm gì nhé! / Dự định làm gì (văn nói thân mật của ～ましょう)",usage:["1. Thể ý chí là thể thân mật (thể ngắn) của cấu trúc 「～ましょう」.","2. Cách chia:","• Nhóm 1: Đổi vần -i sang vần -o rồi thêm う (Ví dụ: いきます -> いこう, のみます -> のもう).","• Nhóm 2: Bỏ る thêm よう (Ví dụ: たべます -> たべよう, みます -> みよう).","• Nhóm 3: します -> しよう, きます -> こよう."],notes:["Sử dụng để rủ rê bạn bè thân thiết hoặc tự nhủ bản thân."],examples:[{ja:"ちょっと 休もう。",romaji:"Chotto yasumou.",vi:"Nghỉ một chút nào!"},{ja:"手伝おうか。",romaji:"Tetsudaouka.",vi:"Để tớ giúp một tay nhé?"}]},{id:4516,lesson:31,level:"N4",title:"V thể ý chí + と思っています",formula:"V thể ý chí + と思っています",meaning:"Tôi/ai đó đang có dự định làm gì",usage:["Diễn tả ý định, kế hoạch đã được ấp ủ từ trước và hiện vẫn đang dự định làm."],notes:["Có thể dùng cho cả dự định của ngôi thứ 3."],examples:[{ja:"週末は デパートで 買い物しようと 思っています。",romaji:"Shuumatsu wa depaato de kaimono shiyou to omotteimasu.",vi:"Cuối tuần tôi định đi mua sắm ở bách hóa."}]},{id:4517,lesson:31,level:"N4",title:"Vる / Vない + つもりです",formula:"Vる / Vない + つもりです",meaning:"Dự định làm / Dự định không làm gì",usage:["Diễn tả quyết định chắc chắn hoặc dự định cá nhân mang tính quả quyết."],notes:["Quyết định mang tính cá nhân rõ rệt hơn ~とおもっています."],examples:[{ja:"明日からは たばこを 吸わない つもりです。",romaji:"Ashita kara wa tabako wo suwanai tsumori desu.",vi:"Từ ngày mai tôi quyết định sẽ không hút thuốc."}]},{id:4518,lesson:31,level:"N4",title:"Vる / Nの + 予定です",formula:"Vる / Nの + 予定です",meaning:"Có kế hoạch / Lịch trình làm gì",usage:["Diễn tả lịch trình, kế hoạch đã được sắp xếp trước (thường do tổ chức hoặc khách quan phân công)."],notes:["Không phụ thuộc vào ý chí bộc phát của bản thân."],examples:[{ja:"7月の 終わりに ドイツへ 行く 予定です。",romaji:"Shichigatsu no owari ni Doitsu he iku yotei desu.",vi:"Cuối tháng 7 tôi có kế hoạch đi Đức."}]},{id:4519,lesson:31,level:"N4",title:"まだ Vていません",formula:"まだ Vていません",meaning:"Vẫn chưa làm V",usage:["Diễn tả một hành động chưa hoàn thành tại thời điểm hiện tại."],notes:["Trả lời cho câu hỏi 「もう Vましたか」."],examples:[{ja:"レポートは もう 書きましたか。…いいえ、まだ 書いていません。",romaji:"Repaato wa mou kakimashitaka. ...Iie, mada kaiteimasen.",vi:"Anh đã viết xong báo cáo chưa? ...Chưa, tôi vẫn chưa viết."}]},{id:4520,lesson:32,level:"N4",title:"Vた / Vない + ほうがいいです",formula:"Vた / Vない + ほうがいいです",meaning:"Nên / Không nên làm gì (khuyên bảo)",usage:["Dùng để đưa ra lời khuyên trực tiếp cho người nghe."],notes:["Mang sắc thái khuyên bảo khá mạnh, nên cẩn thận khi dùng với cấp trên."],examples:[{ja:"毎日 運動した ほうがいいです。",romaji:"Mainichi undou shita hou ga ii desu.",vi:"Bạn nên vận động hàng ngày."},{ja:"お風呂に 入らない ほうがいいです。",romaji:"Ofuro ni hairanai hou ga ii desu.",vi:"Bạn không nên tắm bồn."}]},{id:4521,lesson:32,level:"N4",title:"～でしょう / ～かもしれません",formula:"Thể thường + でしょう / かもしれません",meaning:"Có lẽ là… / Có thể là… (Dự đoán, phỏng đoán)",usage:["1. ～でしょう: Phỏng đoán có độ tin cậy khá cao (70-80%).","2. ～かもしれません: Phỏng đoán có độ tin cậy thấp hơn (khoảng 50%), có lẽ/không chừng."],notes:["Danh từ và tính từ đuôi -na bỏ だ trước でしょう/かもしれません."],examples:[{ja:"明日は 雨が 降るでしょう。",romaji:"Ashita wa ame ga furudeshou.",vi:"Ngày mai có lẽ trời sẽ mưa."},{ja:"約束の時間に 間に合わない かもしれません。",romaji:"Yakusoku no jikan ni maniawanai kamoshiremasen.",vi:"Có thể tôi sẽ không kịp giờ hẹn."}]},{id:4522,lesson:33,level:"N4",title:"Thể mệnh lệnh & Thể cấm đoán (命令形・禁止形)",formula:"V-え / V-ろ (Mệnh lệnh) | V-る + な (Cấm đoán)",meaning:"Mệnh lệnh (sai khiến) & Cấm đoán (không được làm)",usage:["1. Thể mệnh lệnh: Sai khiến, ra lệnh ép buộc ai đó làm gì.","2. Thể cấm đoán: V-る + な (Cấm không được làm gì)."],notes:["Sử dụng chủ yếu bởi nam giới, trong tình huống khẩn cấp hoặc cổ vũ thể thao."],examples:[{ja:"早く 走れ！",romaji:"Hayaku hashire!",vi:"Chạy nhanh lên!"},{ja:"ここに 🛞を 止めるな！",romaji:"Koko ni kuruma wo tomeruna!",vi:"Cấm đỗ xe ở đây!"}]},{id:4523,lesson:33,level:"N4",title:"Cách chia động từ thể mệnh lệnh.（ 命 令 形 ）",meaning:"Cách chia động từ thể mệnh lệnh.（ 命 令 形 ）",usage:["Nhóm I: chuyển đuôi 「u」sang e","(động từ dạng –masu thì bỏ -masu và đổi đuôi –i thành –e)","Thể từ điển Thể ý chí","急ぐ（いそぐ） 急げ（いそげ）","飲む（のむ） 飲め（のめ）","行く（いく） 行け（いけ）","切る（きる） 切れ（きれ）","歌う（うたう） 歌え（うたえ）","持つ（もつ） 持て（もて）","直す（なおす） 直せ（なおせ）","Nhóm II: bỏ る thêm ろ","(động từ dạng –masu thì bỏ -masu và thêm –ro)","Thể từ điển Thể mệnh lệnh","食べる（たべる） 食べろ（たべろ）","起きる（おきる） 起きろ（おきろ）","見る（みる） 見ろ（みろ）","Nhóm III","Thể từ điển Thể mệnh lệnh","する しろ","来る（くる） 来い（こい）","FPT University Tiếng Nhật cơ sở 4"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Cách chia động từ thể mệnh lệnh.（ 命 令 形 ）",romaji:"Cách chia động từ thể mệnh lệnh.（ 命 令 形 ）",vi:"Cách chia động từ thể mệnh lệnh.（ 命 令 形 ）"}]},{id:4524,lesson:33,level:"N4",title:"Cách chia động từ thể cấm đoán（禁止形）",meaning:"Cách chia động từ thể cấm đoán（禁止形）",usage:["Động từ thể từ điển + な","(động từ dạng –masu thì phải chuyển về dạng từ điển và thêm –na)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"行きます",romaji:"行kimasu",vi:""},{ja:"借ります",romaji:"借rimasu",vi:""},{ja:"けっこんします",romaji:"keっkonshimasu",vi:"けっこんする な"}]},{id:4525,lesson:33,level:"N4",title:"Thể mệnh lệnh được dùng để sai khiến, ép buộc ai đó làm một việc gì đó và ngược lại,",meaning:"Thể mệnh lệnh được dùng để sai khiến, ép buộc ai đó làm một việc gì đó và ngược lại,",usage:["thể cấm đoán được dùng để cấm ai đó không làm gì. Cả hai thể này đều mang nghĩa","ép buộc, là kiểu câu mệnh lệnh dạng ngắn nên phạm vi sử dụng khá hẹp, do đó nên","hạn chế dùng chúng một mình ở cuối câu. Thông thường, nam giới hay sử dụng hơn."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Thể mệnh lệnh được dùng để sai khiến, ép buộc ai đó làm một việc gì đó và ngược lại,",romaji:"Thể mệnh lệnh được dùng để sai khiến, ép buộc ai đó làm một việc gì đó và ngược lại,",vi:"Thể mệnh lệnh được dùng để sai khiến, ép buộc ai đó làm một việc gì đó và ngược lại,"}]},{id:4526,lesson:33,level:"N4",title:"Thể mệnh lệnh và cấm đoán được dùng một mình hoặc được dùng ở cuối câu trong",meaning:"Thể mệnh lệnh và cấm đoán được dùng một mình hoặc được dùng ở cuối câu trong",usage:["những trường hợp sau:","a) Người nhiều tuổi nói với người ít tuổi hơn hoặc người địa vị cao nói với người có","địa vị thấp hơn; bố mẹ nói với con cái..."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"b) Giữa bạn bè thân thiết với nhau. Trong trường hợp này, よ được thêm vào cuối",romaji:"b) Giữa bạn bè thân thiết với nhau. Trong trường hợp này, yo được thêm vào cuối",vi:"câu để làm mềm âm điệu."}]},{id:4527,lesson:33,level:"N4",title:"Trong thể văn mệnh lệnh, ngoài cách dùng thể mệnh lệnh, thì “ V ます＋なさい” cũng",meaning:"Trong thể văn mệnh lệnh, ngoài cách dùng thể mệnh lệnh, thì “ V ます＋なさい” cũng",usage:["được dùng. Nó được dùng trong trường hợp bố mẹ nói với con cái, thầy cô giáo với","học sinh. Tuy nhiên sắc thái của nó nhẹ nhàng hơn thể mệnh lệnh. Vì vậy, phụ nữ","thường dùng mẫu câu này thay thế cho thể mệnh lệnh….Tuy nhiên, ta không sử dụng","mẫu câu này với bề trên."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Trong thể văn mệnh lệnh, ngoài cách dùng thể mệnh lệnh, thì “ V ます＋なさい” cũng",romaji:"Trong thể văn mệnh lệnh, ngoài cách dùng thể mệnh lệnh, thì “ V masu＋nasai” cũng",vi:"Trong thể văn mệnh lệnh, ngoài cách dùng thể mệnh lệnh, thì “ V ます＋なさい” cũng"}]},{id:4528,lesson:33,level:"N4",title:"Ｖて＋くれ",meaning:"hãy / xin hãy (làm gì / đừng làm gì)",usage:["nhờ cậy, yêu cầu lịch sự. Mẫu câu này thể hiện ý mệnh lệnh, cấm đoán nhưng nhẹ","nhàng hơn nhiều và không bao hàm ý áp đặt, ép buộc."],notes:[" Chú ý: chỉ có nam giới sử dụng (nữ giới tuyệt đối không sử dụng) và không dùng","với người lớn tuổi hơn hay cấp trên"],examples:[{ja:"Ｖて＋くれ",romaji:"Ｖte＋kure",vi:"hãy / xin hãy (làm gì / đừng làm gì)"}]},{id:4529,lesson:33,level:"N4",title:"～と読みます Đọc là….",meaning:"～と読みます Đọc là….",usage:["～と書いてあります Viết là…."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"(～と trong 2 ví dụ trên có nghĩa giống ～と trong mẫu ~といいます ở bài 21)",romaji:"(～to trong 2 ví dụ trên có nghĩa giống ～to trong mẫu ~toiimasu ở bài 21)",vi:"Ví dụ minh họa"}]},{id:4530,lesson:33,level:"N4",title:"い み",meaning:"X có nghĩa là Y",usage:["Cách diễn đạt ý nghĩa của 1 từ,","Ｘは Ｙと いう 意味です。 cụm từ, biển báo…","(という bắt nguồn từ といいます)","① “ありがとう” は “Cám ơn” という 意味です。","“Arigatou” có nghĩa là “Cám ơn”.","FPT University Tiếng Nhật cơ sở 4","かん じ い み","② Ａ：あの漢字は どいう 意味ですか。(Chữ Hán kia có nghĩa là gì?)","つか い み","Ｂ：使うな という 意味です。 (Nó có nghĩa là “không được dùng”.)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"い み",romaji:"i mi",vi:"X có nghĩa là Y"}]},{id:4531,lesson:33,level:"N4",title:"“Câu văn” と 言 っていました",meaning:"(ai đó) đã nói là / rằng …",usage:["(Thể thường)","ai đó cho người thứ 3.","た なか じ ほんしゃ き","① （電話で）田中さん：１０時に 本社に 来てください。","た なか じ ほんしゃ き い","田中さんは １０時に 本社に 来てくれ と 言っていました。","Anh Tanaka nói là: hãy đến trụ sở công ty lúc 10 giờ","た なか あした やす","② 田中さん： 明 日 休みます。","たなか あ し た やす い","田中さんは 明日 休むと 言っていました。","Anh Tanaka nói là ngày mai anh ấy nghỉ."," Phân biệt: 「～と言いました」và 「～と言っていました」","Giống: cùng dùng để truyền đạt lại 1 câu nói, lời nhắn của ai đó","Khác: 「～と言いました」đặt trọng tâm vào việc ai nói, vào chủ thể của câu nói đó.","Trong khi đó, 「～と言っていました」đặt trọng tâm vào việc truyền đạt lại nội","dung câu nói.","FPT University Tiếng Nhật cơ sở 4"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"“Câu văn” と 言 っていました",romaji:"“Câu văn” to 言 っteimashita",vi:"(ai đó) đã nói là / rằng …"}]},{id:4532,lesson:34,level:"N4",title:"Bài 34 - Điểm ngữ pháp chính",meaning:"sau khi…",usage:["1．","Ｖ １ thể -た","と おりに、Ｖ２","Ｎ の","gì mà mình nghe thấy, nhìn thấy, đọc được....(V1) hoặc theo như hướng dẫn trong 1","cuốn sách, 1 sự chỉ dẫn nào đó… (N)","hợp sẽ khác nhau: (+) với động từ thì chia ở dạng –ta ; (+) với danh từ thì có の; (+)","với số từ thì ghép trực tiếp"],notes:" Chú ý:",examples:[{ja:"V１ た",romaji:"V１ ta",vi:"Số từ"}]},{id:4533,lesson:34,level:"N4",title:"Với mẫu câu này, ở vế 「～たあとで」động tư luôn chia ở thể ～た, không bị ảnh",meaning:"Với mẫu câu này, ở vế 「～たあとで」động tư luôn chia ở thể ～た, không bị ảnh",usage:["hưởng của thời điểm diễn ra"," あした 勉強したあとで、見物に 行きます。"," きのう 勉強したあとで、見物に 行きました。"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Với mẫu câu này, ở vế 「～たあとで」động tư luôn chia ở thể ～た, không bị ảnh",romaji:"Với mẫu câu này, ở vế ～taatodeđộng tư luôn chia ở thể ～ta, không bị ảnh",vi:"Với mẫu câu này, ở vế 「～たあとで」động tư luôn chia ở thể ～た, không bị ảnh"}]},{id:4534,lesson:34,level:"N4",title:"Tổng hợp các cách kết hợp của 「まえに」、「あとで」、「から」",meaning:"Tổng hợp các cách kết hợp của 「まえに」、「あとで」、「から」",usage:["まえに あとで から","Vdict まえに V たあとで V てから","ご飯を食べるまえに、 ご飯を食べたあとで、 ご飯を食べてから、","N のまえに N のあとで N","ご飯のまえに、 ご飯のあとで、","Số từ まえに Số từ あとで Số từ","１時間まえに １時間あとで"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Tổng hợp các cách kết hợp của 「まえに」、「あとで」、「から」",romaji:"Tổng hợp các cách kết hợp của maeni、atode、kara",vi:"Tổng hợp các cách kết hợp của 「まえに」、「あとで」、「から」"}]},{id:4535,lesson:34,level:"N4",title:"Phân biệt sự khác nhau giữa 「～たあとで」và 「～てから」",meaning:"Phân biệt sự khác nhau giữa 「～たあとで」và 「～てから」",usage:["～てから ～たあとで","Diễn tả ý làm ○ドアをノックしてから、部屋に入る ×ドアをノックしたあとで、部屋に入る","hành động A","(sau khi gõ cửa, tôi bước vào phòng)","xong, tiếp ngay","sau đó là hành Khi muốn nhấn mạnh vào tuần tự hành","động B động thì có thể dùng được","○部屋に入るときは必ずノックしたあと","で入ってください","(khi vào phòng thì nhất định gõ cửa","xong hãy vào)","Diễn tả tuần tự けっこん うんてんめんきょ と けっこん うんてんめんきょ と","○ 結婚してから、運転免許を取った。 ○結婚したあとで、運転免許を取った。","các hành động:","A được làm trước (sau khi cưới, tôi đã lấy được bằng lái xe)","và B được làm","sau","Diễn tả thời gian ○日本へ来てから３年になる。 ×日本へ来たあとで３年になる。","(sau khi sang Nhật đã được 3 năm rồi)","FPT University Tiếng Nhật cơ sở 4"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Phân biệt sự khác nhau giữa 「～たあとで」và 「～てから」",romaji:"Phân biệt sự khác nhau giữa ～taatodevà ～tekara",vi:"Phân biệt sự khác nhau giữa 「～たあとで」và 「～てから」"}]},{id:4536,lesson:34,level:"N4",title:"Ｖ１て",meaning:"làm V2 (trong trạng thái) V1",usage:["Ｖ２","Ｖ１ないで","あとで、Ｖ２","tình huống làm nền để 1 hành động khác xảy ra","た はな","あの人は 立っています。そして、話しています。","あの人は 立って、話しています。Người kia đang đứng nói chuyện","(đang nói chuyện trong trạng thái đứng)","すわ はな","わたしは 座っています。そして、話しています。","わたしは 座って、話しています。Tôi đang ngồi nói chuyện.","(đang nói chuyện trong trạng thái ngồi)","ヘルメットをかぶって、運転します。 Đội mũ lái xe (trong trạng thái đội mũ)","めがねを かけて、本を 読みます。 Đeo kính đọc sách (trong trạng thái đeo kính)","めがねを かけないで、本を 読みます。Đọc sách mà không đeo kính","み きかい そうさ","マニュアルを見ないで、機械を操作します。Thao tác máy mà không đọc sách hướng dẫn"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Ｖ１て",romaji:"Ｖ１te",vi:"làm V2 (trong trạng thái) V1"}]},{id:4537,lesson:34,level:"N4",title:"Ｖ １ないで、Ｖ２ (CHỌN 1 TRONG 2)",meaning:"làm V2 mà không làm V1 (chọn 1 trong 2 hành động)",usage:["như dự đoán mà được thay thế bởi một hành động khác."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"①日曜日",romaji:"①日曜日",vi:"どこも"},{ja:"②家で",romaji:"②家de",vi:"ゆっくり 休みます。"},{ja:"①＋②",romaji:"①＋②",vi:"日曜日 どこも"},{ja:"①今晩",romaji:"①今晩",vi:"家へ"},{ja:"②友だちの家に とまります。",romaji:"②友dachino家ni tomarimasu。",vi:"Ví dụ minh họa"},{ja:"①＋②",romaji:"①＋②",vi:"今晩 家へ"}]},{id:4538,lesson:35,level:"N4",title:"Bài 35 - Điểm ngữ pháp chính",meaning:"Bài 35 - Điểm ngữ pháp chính",usage:["「 条 件形」","Động từ thể điều kiện","(Dạng động từ điều kiện loại 3)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 35 - Điểm ngữ pháp chính",romaji:"Bài 35 - Điểm ngữ pháp chính",vi:"Bài 35 - Điểm ngữ pháp chính"}]},{id:4539,lesson:35,level:"N4",title:"Cách chia:",meaning:"chung: nếu…, nếu như… (giống ～と、～たら)",usage:["a) Thể khẳng định:","Động từ:","Nhóm I: Chuyển đuôi「u」sang「e」+ -ba","(động từ dạng –masu thì bỏ -masu và đổi đuôi –i thành –e + ba)","Thể từ điển Thể điều kiện","行く（いく） いけば","急ぐ（いそぐ） いそげば","頼む（たのむ） たのめば","呼ぶ（よぶ） よべば","ある あれば","買う（かう） かえば","待つ（まつ） まてば","話す（はなす） はなせば","Nhóm II: bỏ 「ru」+ -reba","(động từ dạng –masu thì bỏ -masu và thêm –reba)","Thể từ điển Thể mệnh lệnh","調べる（しらべる） しらべれば","変える（かえる） かえれば","見る（みる） みれば","いる いれば","Nhóm III:","来る（くる） くれば","する すれば","FPT University Tiếng Nhật cơ sở 4","Tính từ đuôi i: Bỏ い thêm ければ.","やすい やすければ","ちいさい ちいさければ","いい *よければ","Tính từ đuôi na và danh từ:","+ Tính từ đuôi na bỏ な thêm なら","+ Danh từ thêm なら","(cũng có ならば nhưng なら được dùng nhiều hơn)","かんたん（な） かんたんなら","しずか（な） しずかなら","びょうき びょうきなら","がくせい がくせいなら","b) Thể phủ định:","Động từ: Chuyển từ động từ thể -nai và chia như 1 tính từ đuôi –i","Tính từ đuôi i: Chuyển sang thể phủ định (～くない) và chia như 1 tính từ đuôi –i","Tính từ đuôi na+ danh từ: Chuyển sang thể phủ định (～ではない／～じゃない)","và chia như 1 tính từ đuôi –i","3.1. Diễn đạt điều kiện (hành động, trạng thái ở vế điều kiện) để dẫn đến 1 hành","động, trạng thái ở vế sau (vế kết quả)"],notes:[" Chú ý: khác với 「～と」, vế sau của thể điều kiện loại này có thể là những mẫu","câu diễn đạt ý chí, mong muốn như: 「～Ｖてください」、「Ｖましょう」、「Ｖた","いです」","なに い けん い","(1) 何か 意見が あれば、どうぞ 言ってください。","Nếu có ý kiến gì, xin hãy phát biểu.","みせ やす か","(2) あの店の テレビが 安ければ、買いましょう。","Nếu tivi của cửa hàng kia rẻ thì mua thôi","せんたく き おと しず か","(3) この洗濯機は 音が 静かなら、買いたいです。","Nếu tiếng động của cái máy giặt này êm thì tôi muốn mua.","3.2. Với 「なら」thì có thêm cách sử dụng nữa, với ý: giới hạn đề tài, câu chuyện","được đề cập đến (chỉ trong phạm vi nội dung được nói đến thôi)"],examples:[{ja:"カタログを 見なければ、値段が わかりません。",romaji:"カタログo 見nakereba、値段ga wakarimasen。",vi:"Nếu không xem cuốn catalogue thì không biết được giá."},{ja:"やすければ、この",romaji:"yasukereba、kono",vi:"車を"},{ja:"に ち よう び",romaji:"ni chi you bi",vi:"ひろしま"},{ja:"日曜日は",romaji:"日曜日wa",vi:"ひまなら、広島へ 行きます。"},{ja:"雨なら、うちで テレビを",romaji:"雨nara、uchide テレビo",vi:"見ます。"},{ja:"(1)",romaji:"(1)",vi:"A: 「ワープロが ほしいんですが、どこのほうが いいですか。」"},{ja:"B: 「ワープロなら、東 京 電気が いいです。」",romaji:"B: ワープロnara、東 京 電気ga iidesu。",vi:"A: Tôi muốn có 1 cái máy soạn văn bản, đồ của hãng nào thì tốt nhỉ?"},{ja:"(2)",romaji:"(2)",vi:"A: 「カメラが 買いたいんですが、どこかいい店を知っていますか。」"},{ja:"B: 「カメラなら、秋葉原の藤屋が いいです。」",romaji:"B: カメラnara、秋葉原no藤屋ga iidesu。",vi:"A: Tôi muốn mua 1 cái máy ảnh, bạn có biết cửa hàng nào tốt ko?"},{ja:"(3)",romaji:"(3)",vi:"A: 「あなたは フランス語が 分かりますか。」"},{ja:"B: 「いいえ、分かりません。英語なら、分かります。」",romaji:"B: iie、分karimasen。英語nara、分karimasu。",vi:"A: Bạn có biết tiếng Pháp không?"}]},{id:4540,lesson:36,level:"N4",title:"Bài 36 - Điểm ngữ pháp chính",meaning:"hãy làm thế nào để～",usage:["1.","Vる ように、～。","V ない","đề 1 chỉ mục đích, mệnh đề 2 chỉ hành động có chủ ý để đạt được mục đích ở mệnh đề 1 đưa ra.","tục lâu dài"],notes:["Động từ V る đứng trước ように trong mẫu câu này là động từ không bao hàm chủ","ý mà là động từ thể khả năng, và những động từ như できる、わかる、みえる、きこえる、なる","…","2.","V るように なりました。"," Động từ V る đứng trước ように trong mẫu câu này là động từ thể khả năng và những","động từ như できる、わかる、みえる、きこえる、なる…"," Trong câu nghi vấn V るように なりましたか nếu trả lời bằng いいえ thì sẽ như sau:","FPT University Tiếng Nhật cơ sở 4","漢字が 書けるように なりましたか。Bạn đã viết được chữ Hán chưa?","いいえ、まだ 書けません。Chưa, tôi vẫn chưa viết được.","3.","Vる ように して ください。","V ない"],examples:[{ja:"新聞が",romaji:"新聞ga",vi:"読めるように、漢字を"},{ja:"日本語が",romaji:"日本語ga",vi:"話せるように なりました。"},{ja:"れるように なりました。",romaji:"reruyouni narimashita。",vi:"Lúc đầu tôi không thể ăn được đồ Nhật nhiều lắm nhưng bây giờ có thể ăn được"},{ja:"必 ず",romaji:"必 zu",vi:"時間を"}]},{id:4541,lesson:36,level:"N4",title:"大きな、小さな",meaning:"大きな、小さな",usage:["おお おお ちい ちい","大きな và 大きい, 小さな và 小さい nghĩa giống nhau. Tuy nhiên hơi khác một chút là","sau 大きな、小さな bắt buộc phải là một danh từ."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"大きな、小さな",romaji:"大kina、小sana",vi:"大きな、小さな"}]},{id:4542,lesson:36,level:"N4",title:"かなり:",meaning:"khá, khá là",usage:["một sự phán đoán khách quan."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"今年の",romaji:"今年no",vi:"夏は"}]},{id:4543,lesson:37,level:"N4",title:"Bài 37 - Điểm ngữ pháp chính",meaning:"Bài 37 - Điểm ngữ pháp chính",usage:["Động từ thể Ukemi (受身)：","I. Cách chia:"," Nhóm I: Chuyển [ i ] thành [ are ].","～ます 受身（うけみ）","ききます きかれます","よみます よまれます","はこびます はこばれます","とります とられます","つかいます つかわれます","こわします こわされます"," Nhóm II: Thêm られ.","たべます たべられます","ほめます ほめられます","みます みられます"," Nhóm III:","きます こられます","します されます","II. Thể Ukemi trong bài này sử dụng chủ yếu trong câu bị động:"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 37 - Điểm ngữ pháp chính",romaji:"Bài 37 - Điểm ngữ pháp chính",vi:"Bài 37 - Điểm ngữ pháp chính"}]},{id:4544,lesson:37,level:"N4",title:"Mẫu 1:",meaning:"bị～, được～",usage:["N1(người) は N2(người)に+ Ukemi","。","phía nhận hành động đó.","FPT University Tiếng Nhật cơ sở 4","a) Nghĩa tích cực: Được"],notes:["Trong câu chủ động danh từ 1 là người nhận hành động, được biểu thị bằng trợ","từ を, nhưng trong câu bị động trợ từ を thay bằng trợ từ は để biểu thị chủ từ, danh từ 2 là","người làm hành động biểu thị bằng trợ từ に."],examples:[{ja:"Chủ động: 課長は",romaji:"Chủ động: 課長wa",vi:"私を"},{ja:"Bị động:",romaji:"Bị động:",vi:"私は"},{ja:"Chủ động: 課長は",romaji:"Chủ động: 課長wa",vi:"私を"},{ja:"Bị động:",romaji:"Bị động:",vi:"私は"}]},{id:4545,lesson:37,level:"N4",title:"Mẫu 2:",meaning:"bị～",usage:["N1(người)は N2(người) に N3(vật)を+ Ukemi。","hữu của danh từ 1 và danh từ 1 cảm thấy hành động đó là quấy rầy hay làm phiền","mình."],notes:["Trong mẫu câu này, người làm hành động biểu thị bằng trợ từ に, người nhận sự","quấy rầy hay làm phiền bởi hành động đó biểu thị bằng trợ từ は , vật nhận hành","động biểu thị bằng trợ từ を."],examples:[{ja:"Chủ động: どろぼうは",romaji:"Chủ động: dorobouwa",vi:"（わたしの）"},{ja:"Bị động:",romaji:"Bị động:",vi:"私は"}]},{id:4546,lesson:37,level:"N4",title:"Mẫu 3: N は+ Ukemi。",meaning:"được～",usage:["đó không được đặc biệt chú ý đến, khi đó sự vật sẽ trở thành chủ từ.","FPT University Tiếng Nhật cơ sở 4"],notes:["Khi sự vật không được đặc biệt nhấn mạnh như chủ đề của câu thì は được thay","bằng が.","ここで ボディーが ようせつされます。Thân xe được hàn ở đây.","III. Trợ từ に biểu hiện tỷ lệ:"],examples:[{ja:"一日に",romaji:"一日ni",vi:"1,500 台 自動車が"},{ja:"二人に",romaji:"二人ni",vi:"一人は"}]},{id:4547,lesson:38,level:"N4",title:"Bài 38 - Điểm ngữ pháp chính",meaning:"Bài 38 - Điểm ngữ pháp chính",usage:["DANH TỪ HÓA ĐỘNG TỪ BẰNG TRỢ TỪ の","hay nhóm từ có chứa động từ đó. Câu hay nhóm từ được danh từ hóa có thể làm chủ ngữ","hoặc tân ngữ."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 38 - Điểm ngữ pháp chính",romaji:"Bài 38 - Điểm ngữ pháp chính",vi:"Bài 38 - Điểm ngữ pháp chính"}]},{id:4548,lesson:38,level:"N4",title:"V る＋ のは ＋ A です。 (Câu tính từ với trợ từ は)",meaning:"V る＋ のは ＋ A です。 (Câu tính từ với trợ từ は)",usage:["Đã học (ở bài 8)","サッカーは おもしろいです。 Bóng đá thì thú vị.","Bài này học cách nói cụ thể là “xem bóng đá thì thú vị” hay “chơi bóng đá thì thú vị”","サッカーを するの は おもしろいです。 Chơi bóng đá thì thú vị.","サッカーを 見るの は おもしろいです。 Xem bóng đá thì thú vị.","Các tính từ thường được sử dụng trong mẫu câu này gồm: たのしい、おもしろい、","むずかしい、やさしい、はずかしい、きもちが いい、きけん［な］、 たいへん［な］…"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"V る＋ のは ＋ A です。 (Câu tính từ với trợ từ は)",romaji:"V ru＋ nowa ＋ A desu。 (Câu tính từ với trợ từ wa)",vi:"V る＋ のは ＋ A です。 (Câu tính từ với trợ từ は)"}]},{id:4549,lesson:38,level:"N4",title:"V る＋ のが ＋ A です。 (Câu tính từ với trợ từ が)",meaning:"V る＋ のが ＋ A です。 (Câu tính từ với trợ từ が)",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"(1 ) 私は",romaji:"(1 ) 私wa",vi:"花が"},{ja:"(1’) 私は",romaji:"(1’) 私wa",vi:"花を育てるのが"},{ja:"(2)",romaji:"(2)",vi:"あの人は"},{ja:"(2’) あの人は",romaji:"(2’) ano人wa",vi:"タイプを うつのが"},{ja:"Các tính từ thường được sử dụng trong mẫu câu này gồm: すき［な］、きらい［な］、",romaji:"Các tính từ thường được sử dụng trong mẫu câu này gồm: suki［na］、kirai［na］、",vi:"Ví dụ minh họa"},{ja:"じょうず［な］、へた［な］、はやい、おそい…",romaji:"jiょuzu［na］、eta［na］、wayai、osoi…",vi:"Ví dụ minh họa"}]},{id:4550,lesson:38,level:"N4",title:"V る ＋ の を ＋ わ すれました。 (Câu động từ)",meaning:"Câu (1’) mang hàm ý là “đáng lý ra phải gọi điện nhưng lại quên mất việc đó”. Câu",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"(1 ) 電話番号を",romaji:"(1 ) 電話番号o",vi:"忘れました。"},{ja:"(1’) 電話をかけるのを",romaji:"(1’) 電話okakerunoo",vi:"忘れました。 Tôi đã quên mất việc gọi điện thoại."},{ja:"(2 ) あの人の",romaji:"(2 ) ano人no",vi:"名前を"},{ja:"(2’) レポートに 名前を",romaji:"(2’) レポートni 名前o",vi:"かくのを"}]},{id:4551,lesson:38,level:"N4",title:"V Thể thông thường",meaning:"V Thể thông thường",usage:["Aい ＋のを しっていますか。","Aな Thể thông thường","～だ  な","N"],notes:"Phân biệt しりません và しりませんでした。",examples:[{ja:"FPT だいがくの電話番号を 知っていますか。",romaji:"FPT daigakuno電話番号o 知っteimasuka。",vi:"(N)"},{ja:"セーターの近くで 家事があった のを 知っていますか。",romaji:"セーターno近kude 家事gaaっta noo 知っteimasuka。",vi:"(thể thông thường)"},{ja:"* Lưu ý: Trong mẫu câu này, trợ từ は đi với chủ ngữ trong mệnh đề phụ được đổi thành が。",romaji:"* Lưu ý: Trong mẫu câu này, trợ từ wa đi với chủ ngữ trong mệnh đề phụ được đổi thành ga。",vi:"Bạn có biết việc tuần trước chị Kimura đã kết hôn không?"},{ja:"(1) Q: FPT 大学の電話番号を",romaji:"(1) Q: FPT 大学no電話番号o",vi:"知っていますか。"},{ja:"A: いいえ、しりません。",romaji:"A: iie、shirimasen。",vi:"Bạn có biết số điện thoại của trường đại học FPT không?"},{ja:"(2) Q: 先週",romaji:"(2) Q: 先週",vi:"木村さんが 結婚したのを"},{ja:"A : いいえ、しりませんでした。",romaji:"A : iie、shirimasendeshita。",vi:"Bạn có biết việc tuần trước cô Kimura đã kết hôn không?"},{ja:"thông tin gì từ câu hỏi. Còn ở ví dụ (2) sử dụng しりませんでした vì trong trường hợp này",romaji:"thông tin gì từ câu hỏi. Còn ở ví dụ (2) sử dụng shirimasendeshita vì trong trường hợp này",vi:"người nghe đã nhận được thông tin từ câu hỏi."}]},{id:4552,lesson:38,level:"N4",title:"V Thể thông thường",meaning:"V Thể thông thường",usage:["Aい","＋のは N で す。","Aな Thể thông thường","N ～だ  な","娘は 北海道の 小さい町で 生まれました。","Con gái tôi được sinh ra tại một thành phố nhỏ ở Hokkaido."," 娘が 生まれたのは 北海道の 小さい町です。","Nơi con gái tôi được sinh ra là một thành phố nhỏ ở Hokkaido.","12 月は 1 年で 一番 忙しいです。","Tháng 12 là tháng bận nhất trong một năm."," 1 年で 一番 忙しいのは 12 月です。","Thời gian bận nhất trong một năm là tháng 12.","Mẫu câu này dung khi ta muốn thay thế danh từ chỉ người, vật, nơi chốn… bằng trợ từ,","sau đó đưa nó làm chủ để của câu. Như ta thấy trong ví dụ (1), (2), “nơi mà con gái tôi đã được","sinh ra” và “tháng bận rộn nhất trong một năm” được đưa lên làm chủ đề, sau đó người nói đưa","ra thông tin lien quan ở vế sau."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"V Thể thông thường",romaji:"V Thể thông thường",vi:"V Thể thông thường"}]},{id:4553,lesson:38,level:"N4",title:"の và こ と",meaning:"の và こ と",usage:["Giống như trợ từ の, trợ từ こと mà chúng ta đã học ở bài 18, 19 cũng được sử dụng như"],notes:["là một cách để danh từ hóa động từ. Chú ý nhiều mẫu câu trong đó こと được sử dụng nhưng","の thì không．"],examples:[{ja:"(1) リーさんは 日本語を 話すことが できます。（ ○ ）Anh Lee nói được tiếng Nhật",romaji:"(1) リーsanwa 日本語o 話sukotoga dekimasu。（ ○ ）Anh Lee nói được tiếng Nhật",vi:"Ví dụ minh họa"},{ja:"リーさんは 日本語を 話すのが できます （",romaji:"リーsanwa 日本語o 話sunoga dekimasu （",vi:"×"},{ja:"(2)",romaji:"(2)",vi:"私のしゅみは 映画を 見ることです。（"},{ja:"私のしゅみは 映画を 見るのです。（ ×",romaji:"私noshiゅmiwa 映画o 見runodesu。（ ×",vi:"）"},{ja:"(3) 日本料理を 食べたことが あります。（ ○ ）Tôi đã từng ăn món ăn Nhật.",romaji:"(3) 日本料理o 食betakotoga arimasu。（ ○ ）Tôi đã từng ăn món ăn Nhật.",vi:"Ví dụ minh họa"},{ja:"日本料理を 食べたのが あります。",romaji:"日本料理o 食betanoga arimasu。",vi:"FPT University Tiếng Nhật cơ sở 4"}]},{id:4554,lesson:38,level:"N4",title:"いき và かえり",meaning:"いき và かえり",usage:["Thể ます của một số động từ có thể được sử dụng làm danh từ.","(1) 行きは 道がこんでいましたが、帰りは すいています。","Lúc đi thì đường đông nhưng lúc về thì vắng.","(2) 会社の帰りに 買い物に 行きました。","Trên đường từ công ty về nhà tôi đã đi mua đồ.","Khi thể ます của động từ được sử dụng làm danh từ thì nó không biểu thị hành động của","nó, いき và かえり trong ví dụ (1) chỉ có ý là “lúc đi”, “lúc về”, かえり trong ví dụ (2) có ý là trên","đường về.","FPT University Tiếng Nhật cơ sở 4"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"いき và かえり",romaji:"iki và kaeri",vi:"いき và かえり"}]},{id:4555,lesson:39,level:"N4",title:"V て",meaning:"V て",usage:["V な い なくて (Câu chỉ nguyên nhân, lý do)","、～","A い  A くて","A な で","Những thể văn ở trên được sử dụng để chỉ nguyên nhân, lý do. Trong mẫu câu này, mệnh đề","trước của câu chỉ nguyên nhân và mệnh đề sau chỉ kết quả xảy ra bởi nguyên nhân đó. Khác","với ~から mà chúng ta đã học ở bài 9, mẫu câu này có nhiều hạn chế.","1.1 Mệnh đề sau thường là những từ không bao hàm ý chí, cụ thể:"," Tính từ, động từ biểu hiện cảm xúc: びっくりする、安心する、困る、さびしい、残念だ...","ニュースを聞いて、びっくりしました。 Tôi đã ngạc nhiên khi nghe tin.","暑くて、寝られませんでした。 Không thể ngủ được vì trời nóng."," わからない và thể phủ định của động từ khả năng: いけない、のめない、食べられない...","土曜日は 都合が悪くて、いけません。Tôi không thể đi được vì thứ 7 bận rồi.","話が複雑で、あまりわかりませんでした。Tôi không hiểu lắm vì câu chuyện phức tạp."," Tình huống trong quá khứ:","じこがあって、バスが 遅れてしまいました。Vì có tai nạn nên xe buýt đã đến muộn.","授業に遅れて、先生にしかられました。Vì đến muộn giờ học nên tôi bị thầy giáo mắng.","1.2 Ở mẫu câu này, mệnh đề sau không thể là sự biểu hiện hàm chứa chủ ý (ý hướng,","mệnh lệnh, rủ rê, yêu cầu). Khi mệnh đề sau có nội dung bao hàm chủ ý thì mệnh đề trước","không sử dụng thể て、thay vào đó dùng thể văn から.","あぶないですから、きかいに触らないで ください。（ ○ ）","Vì nguy hiểm, xin đừng sờ vào máy.","あぶなくて、きかいに 触らないで ください。（ × ）","1.3 Trong mẫu câu này, mệnh đề trước và mệnh đề sau của câu có sự liên hệ trước sau về","mặt thời gian. Nghĩa là sự việc của mệnh đề trước có trước, sự việc của mệnh đề sau có sau:","あした 会議が ありますから、今日 準備しなければ なりません。（○）","Vì ngày mai có cuộc họp nên hôm nay phải chuẩn bị.","あした 会議が あって、今日 準備しなければなりません。（×）","FPT University Tiếng Nhật cơ sở 4"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"V て",romaji:"V te",vi:"V て"}]},{id:4556,lesson:39,level:"N4",title:"N で",meaning:"N で",usage:["2.1 Trợ từ で nhiều khi chỉ nguyên nhân, trong trường hợp này danh từ được sử dụng","thường là các từ có đủ sức gây nên một kết quả nào đó như: じこ(tai nạn), じしん (động","đất), かじ (hỏa hoạn)..."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"病気で",romaji:"病気de",vi:"明日 会社を"}]},{id:4557,lesson:39,level:"N4",title:"~の で",meaning:"- Giống như ~ から mà chúng ta đã học ở bài số 9, ～ので chỉ nguyên nhân, lý do. ～か",usage:["V Thể thông thường","Aい ＋ので、～","Aな Thể thông thường","～だ  な","N","FPT University Tiếng Nhật cơ sở 4","3.4 ～ので đi theo thể thông thường như đã trình bày ở trên, khi muốn biểu hiện một cách","lịch sự, lễ phép hơn thì đặt nó đứng sau thể lịch sự:"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"レポートを 書かなければなりませんので、今日は はやく 帰ります。",romaji:"レポートo 書kanakerebanarimasennode、今日wa wayaku 帰rimasu。",vi:"Ví dụ minh họa"},{ja:"（＝レポートを 書かなければならないので、今日は はやく",romaji:"（＝レポートo 書kanakerebanaranainode、今日wa wayaku",vi:"帰ります。）"},{ja:"4. Phân biệt 気持ちがいい",romaji:"4. Phân biệt 気持chigaii",vi:"và"},{ja:"気持ちがいい được sử dụng khi người nói",romaji:"気持chigaii được sử dụng khi người nói",vi:"気分がいい được sử dụng khi người nói"},{ja:"今日は天気がよくて、気持ちがいいです。",romaji:"今日wa天気gayokute、気持chigaiidesu。",vi:"薬を飲んで、熱が下がったので、気分が"},{ja:"Hôm nay trời đẹp khiến tôi cảm thấy sảng",romaji:"Hôm nay trời đẹp khiến tôi cảm thấy sảng",vi:"いいです。"}]},{id:4558,lesson:40,level:"N4",title:"～か Trợ từ nghi vấn",meaning:"～か Trợ từ nghi vấn",usage:["1.1 Trợ từ ～か là trợ từ nghi vấn đã học thường được đặt cuối câu nghi vấn:","A : 会議は 何時に 終わりますか。Mấy giờ thì cuộc họp kết thúc","B : 分かりません。Tôi không biết.","Bài này học:","(1) A+B = 会議は 何時に 終わりますか ＋ 分かりません。","Mấy giờ thì cuộc họp kết thúc？ + không biết"," 会議は 何時に 終わるか、分かりません。","Không biết mấy giờ thì cuộc họp kết thúc.","(2) どうしたら いいですか ＋ 考えてください。","Nên làm thế nào thì tốt? + hãy suy nghĩ"," どうしたら いいか、考えてください。","Hãy suy nghĩ xem nên làm thế nào thì tốt.","(3) 神戸は どんな町ですか ＋ しりません。","Kobe là thành phố như thế nào ? + không biết"," 神戸は どんな町か、しりません。","Không biết Kobe là thành phố như thế nào.","Các ví dụ trên là câu hỏi với từ để hỏi được sử dụng như một thành phần trong câu.","V Thể thông thường","Aい ＋か、～","Aな Thể thông thường","～だ","～","N"],notes:["1.3 Chú ý sự khác nhau giữa なにか trong ví dụ (1), (1’) và どこか trong ví dụ (2),","(2’) sau:","(1) はこの中身は なにか、調べてください。","Hãy kiểm tra xem trong hộp có cái gì.","(1’) のどがかわきましたから、なにか 飲みたいですね。","Vì khát nước nên muốn uống cái gì đó quá nhỉ.","FPT University Tiếng Nhật cơ sở 4","(2) おてあらいは どこか、わかりません。","Không biết nhà vệ sinh ở đâu.","(2’) 今日は いい天気ですね。どこか 行きますか。","Hôm nay trời đẹp quá. Bạn có đi đâu đó không?"],examples:[{ja:"～か Trợ từ nghi vấn",romaji:"～ka Trợ từ nghi vấn",vi:"～か Trợ từ nghi vấn"}]},{id:4559,lesson:40,level:"N4",title:"V Thể thông thường (Có ~ hay không)",meaning:"～かどうか được sử dụng khi một câu văn nghi vấn không có từ nghi vấn",usage:["Aい ＋かどうか、～","Aな Thể thông thường","～だ","～","N"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"(1) リーさんは 来ますか",romaji:"(1) リーsanwa 来masuka",vi:"＋"},{ja:" リーさんは 来るかどうか、分かりません。",romaji:" リーsanwa 来rukadouka、分karimasen。",vi:"Không biết ông Lee có đến không."},{ja:"(2) まちがいが ありませんか ＋",romaji:"(2) machigaiga arimasenka ＋",vi:"しらべてください。"},{ja:"* Lưu ý: Trong ví dụ 2, người ta không dùng “まちがいが あるかどうか” mà dùng",romaji:"* Lưu ý: Trong ví dụ 2, người ta không dùng “machigaiga arukadouka” mà dùng",vi:"“"},{ja:"まちがいが ないかどうか” vì người nói hy vọng rằng không có sự nhầm lẫn nào.",romaji:"machigaiga naikadouka” vì người nói hy vọng rằng không có sự nhầm lẫn nào.",vi:"Ví dụ minh họa"}]},{id:4560,lesson:40,level:"N4",title:"V て みます。 (Thử làm việc gì đó)",meaning:"Mẫu câu diễn đạt ai đó muốn thử làm việc gì để xem kết quả thế nào.",usage:["nguyên thủy là một động từ nên cũng chia như các động từ khác."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"日本の",romaji:"日本no",vi:"お酒を飲んでみたいです。Tôi muốn uống thử rượu của Nhật"},{ja:"ちょっとこの店に 入ってみよう。Chúng ta hãy thử vào quán này một chút đi.",romaji:"chiょっtokono店ni 入っtemiyou。Chúng ta hãy thử vào quán này một chút đi.",vi:"Ví dụ minh họa"},{ja:"このズボンに",romaji:"konoズボンni",vi:"入ってみても いいですか。Tôi có thể mặc thử chiếc quần này không?"}]},{id:4561,lesson:40,level:"N4",title:"Aい  Aさ",meaning:"Aい  Aさ",usage:["Ta có thể biến một tính từ đuôi い sang danh từ trừu tượng miêu tả tính chất, trạng thái","bằng cách đổi đuôi い thành さ."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"高い (cao)",romaji:"高i (cao)",vi:""},{ja:"新しい (mới) ",romaji:"新shii (mới) ",vi:"新しさ (sự mới, cái mới)"},{ja:"山の高さは どうやって",romaji:"山no高sawa douyaっte",vi:"はかるか、知っていますか。"}]},{id:4562,lesson:41,level:"N4",title:"Bài 41 - Điểm ngữ pháp chính",meaning:"Bài 41 - Điểm ngữ pháp chính",usage:["Ở bài 7 và bài 24, chúng ta đã học về các biểu hiện cho và nhận đồ vật hay một hành động","qua việc sử dụng 3 động từ「あげます、もらいます、くれます」. Bài này chúng ta sẽ học","thêm về các biểu hiện cho – nhận phản ánh mối quan hệ Trên - Dưới (địa vị, tuổi tác) ,","quan hệ Trong – Ngoài, quan hệ thân thuộc giữa người cho và người nhận (bao hàm cả","sắc thái tâm lý, tình cảm...).","Quan hệ Trong (ウチ) – Ngoài （ソト）","Trong (ウチ) Ngoài （ソト）","Những người trong gia đình mình Những người ngoài gia đình mình","Những người trong công ty, trường học - Những người ngoài công ty, trường học","hay trong nhóm của mình hay ngoài nhóm của mình.","Người không quen biết","Những người trong nước mình Những người nước ngoài","(Cách thể hiện hành động nhận từ ai cái gì"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 41 - Điểm ngữ pháp chính",romaji:"Bài 41 - Điểm ngữ pháp chính",vi:"Bài 41 - Điểm ngữ pháp chính"}]},{id:4563,lesson:41,level:"N4",title:"～に Ｎを いただきます. giống 「もらいます」nhưng mang hàm ý",meaning:"(mình) nhận (từ ai đó) cái gì",usage:["khiêm nhường của người nói)","hàm ý thể hiện sự khiêm tốn, nhún nhường của người nhận đối với người cho khi người nói","nhận gì đó từ người có tuổi tác, địa vị xã hội cao hơn mình (trừ người trong gia đình), người","không thân quen lắm hoặc khi muốn thể hiện sự tôn trọng đối với người cho mình."],notes:["＊ Chú ý: chủ thể của động từ này luôn luôn là 「わたし」(tôi)","上の人に","わたしは 友達に","（かぞく、父、母など）","下の人に"],examples:[{ja:"わたしは 先生に",romaji:"watashiwa 先生ni",vi:"プレゼントを"},{ja:"わたしは 父に",romaji:"watashiwa 父ni",vi:"お金を いただきます。"},{ja:"Trong trường hợp này, mặc dù 父 (bố) là người trên, người lớn tuổi hơn mình nhưng vì là người nhà",romaji:"Trong trường hợp này, mặc dù 父 (bố) là người trên, người lớn tuổi hơn mình nhưng vì là người nhà",vi:"Ví dụ minh họa"},{ja:"（ウチの人） nên không dùng động từ いただきます mà dùng もらいます。",romaji:"（ウチno人） nên không dùng động từ itadakimasu mà dùng moraimasu。",vi:"Ví dụ minh họa"}]},{id:4564,lesson:41,level:"N4",title:"～は（が）Ｎを くださいます. mình cái gì giống 「くれます」 nhưng hàm",meaning:"(ai đó) cho mình cái gì",usage:["ý tôn kính hơn)","hiện sự tôn trọng của người nhận khi người cho là người có tuổi tác, địa vị xã hội cao hơn","mình (trừ người trong gia đình), hay người không thân quen lắm.."],notes:["＊ Chú ý:","Chủ thể của động từ này luôn là đại từ nhân xưng ngôi thứ 2 hoặc ngôi thứ 3, không","bao giờ là 「わたし」(tôi)","Thể từ điển của 「くださいます」là「くださる」 , và chuyển sang thể -TE là","「くださって」.","上の人は","友達は","（かぞく、父、母など）","下の人は","「くださいます」và 「くれます」 cũng được dùng khi người nhận là người trong gia","đình hay người có quan hệ “Trong” với người nói.","部長は 妹 に おみやげを くださいました。","Trưởng phòng đã cho em gái tôi quà.","(Cách thể hiện hành động cho ai đó cái gì"],examples:[{ja:"社 長 は わたしに",romaji:"社 長 wa watashini",vi:"とけいを"},{ja:"先生は わたしに",romaji:"先生wa watashini",vi:"ボールペンを"},{ja:"Trong trường hợp này, 母 (mẹ) mặc dù là người trên, lớn tuổi hơn mình nhưng vì là người trong gia",romaji:"Trong trường hợp này, 母 (mẹ) mặc dù là người trên, lớn tuổi hơn mình nhưng vì là người trong gia",vi:"Ví dụ minh họa"},{ja:"đình (ウチの人） nên không dùng động từ いただきます mà dùng động từ くれます.",romaji:"đình (ウチno人） nên không dùng động từ itadakimasu mà dùng động từ kuremasu.",vi:"Ví dụ minh họa"},{ja:"母は わたしに",romaji:"母wa watashini",vi:"花を"}]},{id:4565,lesson:41,level:"N4",title:"～に Ｎを やります. giống 「あげます」nhưng chỉ giới hạn dùng",meaning:"(mình) cho ai đó cái gì",usage:["với em trai, em gái, con cái, động thực vật )","hành động có địa vị thấp hơn, ít tuổi hơn (em trai, em gái, con cái trong gia đình), động vật,","thực vật …","上の人に","友達に","（かぞく、父、母など）","下の人に・ 犬／猫／花に"],notes:["Cùng là hành động cho, tặng nhưng trong trường hợp người nói muốn thể hiện sự thái độ tôn kính","với người nhận là người có địa vị, tuổi tác cao hơn thì dùng「さしあげます」","わたしは 社長に ネクタイを さしあげます。","Tôi biếu ông giám đốc chiếc cà vạt.","FPT University Tiếng Nhật cơ sở 5"],examples:[{ja:"わたしは 猫に",romaji:"watashiwa 猫ni",vi:"さかなを"},{ja:"わたしは 花に",romaji:"watashiwa 花ni",vi:"水を やります。"}]},{id:4566,lesson:41,level:"N4",title:"BIỂU HIỆN CỦA HÀNH ĐỘNG CHO VÀ NHẬN",meaning:"làm việc gì (cho ai)",usage:["Vて くださいます","Giống あげます、もらいます、くれます , cả いただきます、くださいます và やります đều kết","hợp với động từ dạng –TE để thể hiện hành động cho, tặng, biếu, nhận nào đó nhưng với sắc thái","tình cảm theo ý nghĩa vốn có của từ mà ta đã tìm hiểu ở trên.","4.1 ～に ～を Vて いただきます (cách nói được ai đó làm cho việc gì )","sự, khiêm nhường hơn so với ～てもらいます。","chủ ngữ của câu luôn là 「わたし」(tôi)","上の人に","友達に","（かぞく、父、母など）","下の人に","giúp đỡ.","khác với ～ていただきます chủ ngữ là người nhận, còn trong câu ～てくだ","さいます chủ ngữ là người thực hiện hành động.","FPT University Tiếng Nhật cơ sở 5","上の人は","友達は","（かぞく、父、母など）","下の人は","gái, con cái trong gia đình hay với động, thực vật) con gái","上の人に","わたしは 友達に","下の人に・ 犬／猫／花に"],notes:["- Cũng giống như 「V てあげます」đã giải thích ở bài 24, nếu sử dụng「V てさしあげます」","với ý làm gì đó cho người trên sẽ dễ gây cảm giác ép buộc, không tự nhiên. Vì thế, trong trường hợp","này người ta thường không dùng cách nói này, mà sẽ dùng cách nói khiêm nhường sẽ học ở bài 50","FPT University Tiếng Nhật cơ sở 5"],examples:[{ja:"私 は 鈴木さんに",romaji:"私 wa 鈴木sanni",vi:"日本語を 教えて いただきました。"},{ja:"私 は 中村さんに",romaji:"私 wa 中村sanni",vi:"本社へ"},{ja:"部長の奥さんは（ 私 に）日本料理を",romaji:"部長no奥sanwa（ 私 ni）日本料理o",vi:"作って"},{ja:"会社の人は（ 私 に）この機械の使い方を",romaji:"会社no人wa（ 私 ni）kono機械no使i方o",vi:"教えてく"},{ja:"わたしは 犬を",romaji:"watashiwa 犬o",vi:"散歩に"},{ja:"わたしは 社長に",romaji:"watashiwa 社長ni",vi:"写真を"},{ja:"わたしは 社長に 写真を お見しました。",romaji:"watashiwa 社長ni 写真o o見shimashita。",vi:"ĐÚNG"},{ja:"お子さんに",romaji:"o子sanni",vi:"どんな おみやげを"},{ja:"…とけいか",romaji:"…tokeika",vi:"ラジカセを"},{ja:"Trường hợp này「お子さん」(con của người khác) nên người hỏi cũng phải dùng cách nói lịch",romaji:"Trường hợp nàyo子san(con của người khác) nên người hỏi cũng phải dùng cách nói lịch",vi:"Ví dụ minh họa"},{ja:"sự là 「～V てあげますか」chứ không dùng 「～V てやりますか」。",romaji:"sự là ～V teagemasukachứ không dùng ～V teyarimasuka。",vi:"(cách yêu cầu, đề nghị ai làm gì giúp mình"}]},{id:4567,lesson:41,level:"N4",title:"~V ていただけませんか。",meaning:"mong (ai đó) làm gì giúp được không?",usage:["1 cách lịch sự )","mình hay người không quen biết, lịch sự hơn V てくださいませんか。."],notes:"「～ていただけませんか」 chứ không phải là 「～ていただきませんか。」",examples:[{ja:"すみませんが、もう一度",romaji:"sumimasenga、mou一度",vi:"説明して"},{ja:"V 手紙の",romaji:"V 手紙no",vi:"書き方が"},{ja:"V て。",romaji:"V te。",vi:"(Bài 20)"},{ja:"×V て いただきませんか。",romaji:"×V te itadakimasenka。",vi:"×V ないで"}]},{id:4568,lesson:42,level:"N4",title:"～ために、 (cách thể hiện mục đích)",meaning:"Để",usage:["～","biểu hiện mục đích, mệnh đề sau biểu hiện hành vi có ý chí để thực hiện mục đích ấy.","Có 2 cách sử dụng: với động từ và với danh từ như sau:","1.1 V1 るために、V2 (Để thực hiện V1 thì V2)","Động từ đi trước ｢ために｣ là động từ thể từ điển và là những động từ mang tính ý chí thể hiện 1","mục đích nào đó."],notes:["1/ Phân biệt「～ように」(bài 36) với「～ために」","Sự giống nhau:","Mệnh đề trước là mục đích của mệnh đề sau, mệnh đề sau là hành vi để đạt được mục đích ấy.","Động từ được sử dụng ở mệnh đề trước là động từ có tính ý chí. Còn ở mệnh đề sau, cả động","từ có tính ý chí và động từ không có tính ý chí đều sử dụng được.","Cả「～ように」và「～ために」đều đi với động từ ở thể từ điển. (Người ta không hay dùng","dạng 「V ないために」)。","Sự khác nhau:","Ở mệnh đề trước – mệnh đề thể hiện mục đích của mẫu câu 「～ように」có thể sử dụng cả","động từ không có tính ý chí.","2/ Động từ có tính ý chí và động từ không có tính ý chí:","Động từ có tính ý chí là động từ thể hiện những động tác, hành động mà ý chí của con người","có thể điều khiển được.. VD: たべる(ăn), のむ (uống), いく (đi), つくる (tạo ra), ねる (ngủ)....","FPT University Tiếng Nhật cơ sở 5","Động từ không có tính ý chí là động từ thể hiện những động tác, hành động mà ý chí của","con người không thể điều khiển được, bao gồm:","+ Sự vận động, trạng thái của những vật vô tri, vô giác: ある(có), 壊れる (bị vỡ), 雨が降る","(mưa rơi), 風が吹く (gió thổi), 水が出る (nước chảy)...","+ Các hiện tượng sinh lý của con người:痛む(đau), 病気になる (bị ốm), 老いる(già) , 若返","る (trẻ lại), 目が覚める(tỉnh dậy)...","+ Các hiện tượng tâm lý của con người : 困る(khó khăn) , 飽きる (mệt mỏi), できる (có","thể)... và các động từ ở thể khả năng.","Tuy nhiên, ngoài các ví dụ trên, có nhiều trường hợp cùng là 1 từ nhưng tùy vào văn cảnh và","cách sử dụng khác nhau mà động từ đó có thể lúc là có tính ý chí, lúc là không có tính ý chí."],examples:[{ja:"らいねん 世界旅行を",romaji:"rainen 世界旅行o",vi:"するために、今"},{ja:"漢字を",romaji:"漢字o",vi:"勉 強 するために、辞書を 買いました。"},{ja:"* Kiến thức nâng cao, mở rộng: Trong mẫu câu 「～ために」, nếu mệnh đề trước là động từ",romaji:"* Kiến thức nâng cao, mở rộng: Trong mẫu câu ～tameni, nếu mệnh đề trước là động từ",vi:"không có tính ý chí hay là các hiện tượng tự nhiên thì mệnh đề đó không phải chỉ mục đích mà sẽ trở"},{ja:"毎日 雨が降ったために、橋が 壊れた。Cây cầu bị hỏng do ngày nào trời cũng mưa.",romaji:"毎日 雨ga降っtatameni、橋ga 壊reta。Cây cầu bị hỏng do ngày nào trời cũng mưa.",vi:"Ví dụ minh họa"},{ja:"Khi kết hợp với danh từ, mệnh đề 「N のために」mang 2 ý nghĩa:",romaji:"Khi kết hợp với danh từ, mệnh đề N notamenimang 2 ý nghĩa:",vi:"① ・Nếu là những danh từ chỉ sự việc, thì mệnh đề này cũng thể hiện mục đích (giống với"},{ja:"mẫu cầu với động từ「V るために」)",romaji:"mẫu cầu với động từV rutameni)",vi:"Ví dụ minh họa"},{ja:"健康のために、たばこを やめた。Tôi bỏ thuốc lá (để) cho khỏe.",romaji:"健康notameni、tabakoo yameta。Tôi bỏ thuốc lá (để) cho khỏe.",vi:"Ví dụ minh họa"},{ja:"発 表 の 準 備のために、本を",romaji:"発 表 no 準 備notameni、本o",vi:"借りました。Tôi đã mượn sách để chuẩn bị phát biểu"},{ja:"台風のために、木が",romaji:"台風notameni、木ga",vi:"倒れた。Cây đổ tại (vì) bão."},{ja:"か ぞく",romaji:"ka zoku",vi:"いっしょうけんめい"},{ja:"家族のために、一 生 懸命",romaji:"家族notameni、一 生 懸命",vi:"働 かなければなりません。Tôi phải cố làm việc hết sức vì gia đình."},{ja:"奥さんのために、 新 しいバイクを買うつもりです。Tôi định mua 1 chiếc xe máy mới vì/cho vợ.",romaji:"奥sannotameni、 新 shiiバイクo買utsumoridesu。Tôi định mua 1 chiếc xe máy mới vì/cho vợ.",vi:"FPT University Tiếng Nhật cơ sở 5"}]},{id:4569,lesson:42,level:"N4",title:"V るのに 使います／便利です...",meaning:"(sử dụng) vào việc gì / (có lợi) cho việc gì / (cần thiết) cho cái gì",usage:["(1 cách sử dụng nữa của trợ từ に:","つか ひつよう thể hiện mục đích)","N に 使います／必要です...","dùng 「Ｎに」, nếu kết hợp với động từ thì dùng phương pháp “danh từ hóa động từ” (「曲","げるのに」)","＊ Lưu ý: riêng với các động từ nhóm III có dạng「Ｎします」thì khi kết hợp, không kết hợp theo","kiểu 「Ｎするのに」mà ghép thẳng thành「Ｎに」.","VD: ・勉強します 勉強に","・修理します 修理に","Về ý nghĩa thể hiện mục đích, mẫu câu này khá giống với 「（の）ために」nhưng không mạnh","mẽ bằng và mệnh đề sau của mẫu câu này thường chỉ giới hạn ở 1 số động từ, tính từ mang","tính trạng thái như:","・「~ に使います」(cách sử dụng)","・「~ に便利です、必要です、いいです、役に立ちます…」(đánh giá)","・「~ に（時間、お金）がかかります」(tính toán)...","①このはさみは 紙を 切るのに 使います。 Cái kéo này dùng để cắt giấy.","②この ミキサーは 何に 使うんですか。 Cái máy trộn này dùng để làm gì thế?.","…原 料を まぜるのに 使います。 Dùng để trộn nguyên liệu.","b) （N は）V るのに 便利です/必要です/いいです/役に立つ : đánh giá","じしょ かんじ しら べん り","この辞書は 漢字を調べるのに 便利です。Cuốn từ điển này rất tiện cho việc tra chữ Hán.","この本は 日本のことを知るのに 役に立ちます。Quyển sách này có ích cho việc tìm hiểu NB.","c) （N は）V るのに（時間、お金）が かかります : tính toán","この時計は 直すのに １週間 かかります。 Cái đồng hồ này phải mất 1 tuần để sửa.","FPT University Tiếng Nhật cơ sở 5","THAM KHẢO:","1/ Chúng ta đã từng gặp trợ từ 「に」thể hiện mục đích trong những bài trước như:","① 本を買いに行きます（Bài 13）","Đi để mua sách.","② 体にいい／悪い（Bài 32）","Tốt/không tốt cho sức khỏe","に ほ ん ご しんぶん よ まいにち れんしゅう","③ 日本語の新聞が 読めるように、毎日 練 習 します（Bài 36）","Ở bài này, chúng ta lại học thêm 2 cách thể hiện mục đích nữa của trợ từ 「に」là","「～ために」và「～（の）に」.","2/ So sánh các mẫu câu thể hiện mục đích 「~に」「~ように」「～ために」「～（の）に」","行く","に 来る（Bài 13） ように ために (の)に","帰る （Bài 36） （Bài 42） （Bài 42）","Mẫu câu","Vる","V ます に V ない ように V るために V るのに","Mệnh đề Mệnh Mệnh đề Mệnh đề Mệnh đề Mệnh đề","行く trước đề sau trước sau trước sau","Động từ có","tính ý chí に 来る - Động từ không - Động từ Aい","帰る Động từ Động từ Động từ","Cách có tính ý chí có tính ý","có tính ý có tính ý có tính ý Aな","dùng (Câu đơn) - Động từ thể khả chí","chí chí chí Động từ","năng - Động từ","trạng thái","trạng thái","Đi (đến, trở về) một Ở mệnh đề trước, sự việc trở Nhấn mạnh vào ý mục So với「ために」thì","nơi nào đó để làm việc thành có khả năng là mục đích của mệnh đề trước tính mục đích yếu","gì (động từ có tính ý đích, mệnh đề sau thể hiện hơn. Mệnh đề sau thể","chí ở đây là mục đích) sự nỗ lực để tiến đến khả hiện trạng thái"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"(・子どもが早く起きるよう",romaji:"( 子domoga早ku起kiruyou",vi:"nhất."},{ja:"に、目覚し時計を買った)",romaji:"ni、目覚shi時計o買っta)",vi:"Tôi đã mua đồng hồ báo"}]},{id:4570,lesson:43,level:"N4",title:"Bài 43 - Điểm ngữ pháp chính",meaning:"Bài 43 - Điểm ngữ pháp chính",usage:["(Diễn đạt sự suy đoán về tình trạng ngay"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 43 - Điểm ngữ pháp chính",romaji:"Bài 43 - Điểm ngữ pháp chính",vi:"Bài 43 - Điểm ngữ pháp chính"}]},{id:4571,lesson:43,level:"N4",title:"Ｖそうです trước khi có sự thay đổi)",meaning:"có vẻ",usage:["tượng có được từ 1 hiện tượng mà mình nhìn thấy tận mắt hay giải thích về tình trạng sự","vật, sự việc ngay trước khi nó thay đổi."," Cách chia:","Ｖます＋そうです／だ","sự vật, sự việc nào đó. Có thể hiểu nôm na mẫu câu này là “nhìn và nghĩ là, cho là nó như","thế”."," Cách chia:","Ａいです  Ａいそうです／だ","Ｎａです  Ｎａそうです／だ","Trường hợp đặc biệt: いいです  よさそうです／だ","ないです  なさそうです／だ","FPT University Tiếng Nhật cơ sở 5"],notes:["「Chú ý」:","・không áp dụng cách nói này đối với những tính từ thể hiện trạng thái quá rõ ràng, nhìn thấy","ngay bên ngoài…, ví dụ như: 「赤い、きれい、有名、かわいい」","× このりんごは 赤そうです。","Quả táo này có vẻ đỏ. (sai vì bề ngoài là màu đỏ)","○ このすいかは 中が 赤そうです。","Quả dưa hấu này bên trong có vẻ đỏ.","(đúng vì từ bên ngoài không biết được, chỉ phán đoán)","・Đối với các tính từ thể hiện tình cảm hoặc cảm giác của con người như「うれしい、さびしい、","かなしい、いたい、気分が悪い、気分がいい」, vì chúng ta không thể diễn đạt, miêu tả một","cách trực tiếp cảm giác, tình cảm, tâm trạng của người khác mà chỉ có thể suy đoán nên phải","dùng「～そうです」"],examples:[{ja:"曇っていますね。雨が",romaji:"曇っteimasune。雨ga",vi:"降りそうです。 Bầu trời nhiều mây quá. Trời sắp mưa."},{ja:"これから 寒くなりそうです。",romaji:"korekara 寒kunarisoudesu。",vi:"Trời sắp lạnh."},{ja:"今にも 荷物が",romaji:"今nimo 荷物ga",vi:"落ちそうです。Hành lý sắp rơi."},{ja:"煙 が 少なくなりました。火事は",romaji:"煙 ga 少nakunarimashita。火事wa",vi:"消えそうです。Khói ít đi rồi. Cơn hỏa hoạn sắp tắt."},{ja:"Ａ／Ｎａそうです",romaji:"Ａ／Ｎａsoudesu",vi:"Ví dụ minh họa"},{ja:"この 料 理は",romaji:"kono 料 理wa",vi:"おいしそうです。"},{ja:"彼女は",romaji:"彼女wa",vi:"忙 しそうです。"},{ja:"彼は 暇そうです。",romaji:"彼wa 暇soudesu。",vi:"Anh ấy có vẻ rảnh rỗi."},{ja:"あのケーキは おいしくなさそうです。 Cái bánh kia có vẻ không ngon.",romaji:"anoケーキwa oishikunasasoudesu。 Cái bánh kia có vẻ không ngon.",vi:"Ví dụ minh họa"},{ja:"・Mẫu câu 「～そうです」này không kết hợp với danh từ",romaji:"Mẫu câu ～soudesunày không kết hợp với danh từ",vi:"Tham khảo – Mở rộng:"},{ja:"Sự khác nhau giữa 「～でしょう」và「 ～そうです」：",romaji:"Sự khác nhau giữa ～deshiょuvà ～soudesu：",vi:"Ví dụ minh họa"},{ja:"「～でしょう」biểu thị suy luận của người nói căn cứ vào một số thông tin nào đó còn",romaji:"～deshiょubiểu thị suy luận của người nói căn cứ vào một số thông tin nào đó còn",vi:"Ví dụ minh họa"},{ja:"「～そうです」 biểu thị suy luận của người nói theo điều mà người nói quan sát được.",romaji:"～soudesu biểu thị suy luận của người nói theo điều mà người nói quan sát được.",vi:"(Người nói có thể nghe thông tin qua đài, báo..rồi nói)"}]},{id:4572,lesson:43,level:"N4",title:"(Cách diễn đạt đi đâu đó, làm gì đó rồi",meaning:"làm gì đó (rồi sẽ trở lại)",usage:["V て来ます quay lại)","câu này là với 1 câu nhưng bao hàm 3 hành động","(1) đi đâu đó  (2) làm gì đó  (3) quay trở lại"],notes:["Địa điểm đi đến và thực hiện hành động ở đó được thể hiện bằng trợ từ 「で」. Tuy","nhiên, khi địa điểm đó là nơi lấy đi (hoặc di chuyển) một vật thì ta dùng trợ từ 「から」.","スーパーで 牛 乳を 買って来ます。 Tôi đi đến mua sữa ở siêu thị.","だいどころ こ っ ぷ と","台 所 から コップを 取って来ます。 Tôi đi lấy cốc từ nhà bếp.","So sánh – Mở rộng:","Sự khác nhau giữa 「（場所）へＶに行く」「（場所）でＶて来る」","あの店へ 買いに 行きます。 あの店で 買って来ます。","① あの店へ 行く ① あの店へ 行く","② あの店で 買う。 ② あの店で 買う","③ あの店から 来る","Chỉ bao hàm 2 hành động","Bao hàm 3 hành động","FPT University Tiếng Nhật cơ sở 5"],examples:[{ja:"教 室に",romaji:"教 室ni",vi:"時計を"}]},{id:4573,lesson:44,level:"N4",title:"Bài 44 - Điểm ngữ pháp chính",meaning:"Bài 44 - Điểm ngữ pháp chính",usage:["Cách tạo từ mới có nghĩa rộng hơn so với nghĩa của từ gốc"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 44 - Điểm ngữ pháp chính",romaji:"Bài 44 - Điểm ngữ pháp chính",vi:"Bài 44 - Điểm ngữ pháp chính"}]},{id:4574,lesson:44,level:"N4",title:"Ｖ、Ａ、Ｎａ＋すぎます",meaning:"dễ (làm gì)…., khó (làm gì)….",usage:["thái, tình trạng. Do đó, mẫu câu này thường được dùng trong những trường hợp có ý xấu,","nằm ngoài mong đợi của người nói."," Cách ghép:","Ｖます  Ｖます","Ａいです  Ａい ＋すぎます","Ｎａです  Ｎａ","thực hiện hành động nào đó"," Cách chia:","Ｖます  Ｖます ＋ やすいです","Ｖます  Ｖます ＋ にくいです"],notes:["「すぎます」là động từ nhóm II  「すぎる、すぎて」","た いた","食べすぎて、おなかが 痛いです。 Vì tôi ăn nhiều quá nên bị đau bụng.","し けん もんだい ふくざつ なに","試験の問題は 複雑すぎて、何も わかりませんでした。Bài thi khó quá nên chả hiểu gì cả.","す の からだ わる","いくら好きでも、飲みすぎると、 体 に悪いですよ。","Dù có thích rượu mấy đi chăng nữa nhưng nếu uống nhiều quá cũng có hại cho sức khỏe.","Edited by Foxit Reader","FPT University Tiếng Nhật cơ sở 5","Copyright(C) by Foxit Software Company,2005-2008","Japanese Language Training Division For Evaluation Only. Giải thích văn phạm","2.","Ｖやすい／にくいです","「Chú ý」: sau khi ghép, cả cụm từ đó mang tính chất của 1 tính từ đuôi –i. Vì thế, nó tuân","thủ toàn bộ các quy tắc, mẫu câu đã học đối với tính từ đuôi –i.","この薬は 砂糖を入れると、飲みやすく なります。","Nếu cho đường vào thì thuốc này sẽ (trở nên) dễ uống hơn.","このコップは 割れにくくて、安全ですよ。","Cái cốc này khó vỡ nên an toàn đấy.","FPT University Tiếng Nhật cơ sở 5"],examples:[{ja:"昨日の晩",romaji:"昨日no晩",vi:"お酒を"},{ja:"お土産を",romaji:"o土産o",vi:"買いすぎました。"},{ja:"寿司を",romaji:"寿司o",vi:"食べすぎました。"},{ja:"このシャツは",romaji:"konoシャツwa",vi:"大きすぎます。"},{ja:"この本は",romaji:"kono本wa",vi:"複雑すぎます。"},{ja:"この 薬 は",romaji:"kono 薬 wa",vi:"飲みやすいです。"},{ja:"このコンピューターは",romaji:"konoコンピューターwa",vi:"使いやすいです。"},{ja:"白いシャツは",romaji:"白iシャツwa",vi:"汚れやすいです。"},{ja:"東 京は",romaji:"東 京wa",vi:"住みにくいです。"},{ja:"このコップは",romaji:"konoコップwa",vi:"割れにくいです。"}]},{id:4575,lesson:44,level:"N4",title:"Ａい く ＋ します",meaning:"làm cho ~ trở thành",usage:["Ｎａ に","Ｎ ＋ に","nghĩa “một cái gì đó chuyển sang trạng thái khác (trở nên, trở thành 1 cách tự nhiên)”, còn","trong bài này, chúng ta học cách tạo phó từ với động từ「～します」với ý nghĩa “làm thay","đổi một cái gì đó sang một trạng thái khác (làm cho ~ trở thanh hoàn toàn do ý chí)”."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"部屋を",romaji:"部屋o",vi:"きれいに"},{ja:"塩の 量 を",romaji:"塩no 量 o",vi:"半分に"}]},{id:4576,lesson:44,level:"N4",title:"Ｎに します",meaning:"chọn, quyết định (làm)",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"会議は",romaji:"会議wa",vi:"明日に"},{ja:"晩ご飯は",romaji:"晩go飯wa",vi:"寿司に"},{ja:"ホテルは",romaji:"ホテルwa",vi:"どこに"},{ja:"… ハノイホテルに",romaji:"… ハノイホテルni",vi:"します。"}]},{id:4577,lesson:45,level:"N4",title:"Bài 45 - Điểm ngữ pháp chính",meaning:"Trong trường hợp…, Nếu…",usage:["Ｖた","1.","Ｖない ばあい (Cách diễn đạt giả định)","Ａい ＋ 場合は、～","Ａな","Ｎの","mẫu câu 「～たら」) nhưng thường chỉ dùng trong những tình huống không hay, không","mong đợi hoặc những điều hiếm khi xảy ra. Hành động ở vế sau thể hiện điều cần phải làm","trong trường hợp đó hoặc kết quả do tình huống đó đem lại. Bản thân「場 合 」 là một danh","từ nên nó kết hợp với các loại từ khác (động từ, tính từ, danh từ) theo đúng các quy tắc đã","học."],notes:["trên thực tế, cũng có mẫu câu 「Ｖdict.場合は」nhưng tính giả định của mẫu câu này","không mạnh bằng 「Ｖた場合は」và trong giáo trình này chỉ dùng mẫu câu 「Ｖた場合は」","Với tính từ:","ちょう し わる ば あい","ファックスの 調 子が 悪い 場合は、どうしたらいいですか。","Tôi nên làm thế nào trong trường hợp máy fax gặp trục trặc?","FPT University Tiếng Nhật cơ sở 5","パスポートが 必要な 場合は、彼に言ってください。","Anh hãy nói với anh ý trong trường hợp cần hộ chiếu.","Với danh từ:","か じ じ しん ば あい つか","家事や 地震の 場合は、エレベーターを 使わないでください。","Trong trường hợp xảy ra động đất và hỏa hoạn, không được dùng cầu thang máy.","・Khi muốn nhấn mạnh, có thể thêm cụm từ 「万一」hoặc「万が一」(vạn nhất) vào phía đầu của","vế có 「～場合は」","・Giáo trình này không đề cập đến cách kết hợp với các dạng: quá khứ phủ định của động từ, quá","khứ hay phủ định của tính từ, danh từ.","Ｖる"],examples:[{ja:"じ かん",romaji:"ji kan",vi:"おく"},{ja:"時間に遅れた",romaji:"時間ni遅reta",vi:"場合は、 教 室に"},{ja:"雨が降った",romaji:"雨ga降っta",vi:"場合は、学校を"},{ja:"かい ぎ",romaji:"kai gi",vi:"ま"},{ja:"会議に間に合わない",romaji:"会議ni間ni合wanai",vi:"場合は、連絡してください。"},{ja:"さん か",romaji:"san ka",vi:"ば あい"},{ja:"参加できない",romaji:"参加dekinai",vi:"場合は、 私 に"}]},{id:4578,lesson:45,level:"N4",title:"(Cách diễn đạt nghịch lý)",meaning:"…thế mà, vậy mà…",usage:["Ａい","Thể thường ＋ のに、～","Ｎａな","Ｎ な","tình huống nào đó. Điểm khác biệt cần lưu ý ở mẫu câu này (so với cách nói cùng ý nghĩa","như 「～が」hay「～ても」)là nó bao hàm những tình cảm, cảm giác mạnh mẽ của người","nói như sự bất mãn, không ngờ…"],notes:["「Chú ý」:","FPT University Tiếng Nhật cơ sở 5","・Sự khác nhau giữa「～のに」và「 ～が/～ても」","① 私 の部屋は 狭いですが、きれいです。（８課）","Phòng của tôi hẹp nhưng mà đẹp.","② 明日 雨が 降っても、出かけます。（２５課）","Ngày mai, dù trời có mưa chăng nữa, tôi vẫn đi ra ngoài.","やくそく こ","③ 約束したのに、どうして 来なかったんですか。","Đã hứa rồi mà sao bạn lại không đến vậy?","ví dụ ①: chỉ đơn thuần có ý gắn nối 2 sự đánh giá có tính đối lập, không bao hàm ý","chỉ kết quả nằm ngoài mong đợi.","ví dụ ②: chỉ dùng để giả định về 1 việc chưa xảy ra trong hiện thực","ví dụ ③: mang ý ngược nghĩa, nghịch lý giữa 2 vế nhưng có bao hàm cảm giác thất","vọng, bất mãn hay không ngờ trong câu nói","・「～のに」có ý nghĩa hoàn toàn ngược với「～ので」","一生懸命 勉強したので、１００点を もらった。","一生懸命 勉強したのに、５０点しか もらえなかった。","・Chú ý phân biệt giữa mẫu câu chỉ mục đích「～（の）に」(bài 42) và mẫu câu diễn đạt","nghịch lý「～のに」của bài này.","FPT University Tiếng Nhật cơ sở 5"],examples:[{ja:"ダイエットしているのに、太ってしまいました。Tôi đã ăn kiêng thế mà vẫn bị béo.",romaji:"ダイエットshiteirunoni、太っteshimaimashita。Tôi đã ăn kiêng thế mà vẫn bị béo.",vi:"Ví dụ minh họa"},{ja:"約束をしたのに、彼女は",romaji:"約束oshitanoni、彼女wa",vi:"来ませんでした。Hẹn rồi vậy mà cô ấy không đến."},{ja:"ボタンを押したのに、コピーできません。Tôi đã ấn nút rồi thế mà vẫn không thể copy.",romaji:"ボタンo押shitanoni、コピーdekimasen。Tôi đã ấn nút rồi thế mà vẫn không thể copy.",vi:"Ví dụ minh họa"},{ja:"古くて、狭いのに、家賃は",romaji:"古kute、狭inoni、家賃wa",vi:"高いです。 Nhà vừa cổ lại hẹp thế mà tiền nhà lại đắt đỏ."},{ja:"今日は日曜日なのに、 働 かなければなりません。Hôm nay là chủ nhật mà tôi vẫn phải làm việc.",romaji:"今日wa日曜日nanoni、 働 kanakerebanarimasen。Hôm nay là chủ nhật mà tôi vẫn phải làm việc.",vi:"Ví dụ minh họa"},{ja:"このレストランは有名なのに、おいしくないです。Nhà hàng này nổi tiếng thế mà chẳng ngon.",romaji:"konoレストランwa有名nanoni、oishikunaidesu。Nhà hàng này nổi tiếng thế mà chẳng ngon.",vi:"Ví dụ minh họa"}]},{id:4579,lesson:46,level:"N4",title:"～ところです (cách mẫu câu với cụm từ ところです)",meaning:"mới / vừa mới (làm ～)",usage:["Trước đây, ở bài 8 ta đã học từ 「ところ」với ý nghĩa là nơi, chỗ (chỉ vị trí, địa điểm). Đến bài này","「ところ」sẽ được mở rộng hơn với 1 ý nghĩa khác: “thể hiện thời điểm” với mẫu câu","V ところです","mạnh vào thời điểm trước khi diễn ra hành động đó. Mẫu câu này thường đi kèm với các","cụm từ chỉ thời điểm như: 「これから、」、「（ちょうど）今から」","vào thời điểm hành động đang xẩy ra (mạnh hơn V ています). Mẫu câu này thường đi","kèm với trạng từ chỉ thời gian 「今」","FPT University Tiếng Nhật cơ sở 5","điểm ngay sau khi hành động hoàn thành. Mẫu câu này chỉ đi được với trạng từ chỉ thời","gian 「たった今」","chưa lâu lắm. Thời điểm xẩy ra chưa lâu đó hoàn toàn là do phán đoán chủ quan của","người nói (có thể là mới đây hoặc cũng có thể là đã lâu rồi)"],notes:"・Tất cả các mẫu câu ～ところです đều mang ý tả lại trạng thái tại 1 thời điểm 1 cách đơn thuần.",examples:[{ja:"(1) A: 昼ご飯は",romaji:"(1) A: 昼go飯wa",vi:"もう"},{ja:"B: いいえ、これから",romaji:"B: iie、korekara",vi:"食べるところです。…Chưa, tôi chuẩn bị ăn bây giờ."},{ja:"(2) A: 会議は",romaji:"(2) A: 会議wa",vi:"もう"},{ja:"B: いいえ、今から 始まるところです。…Chưa, sắp sửa bắt đầu.",romaji:"B: iie、今kara 始marutokorodesu。…Chưa, sắp sửa bắt đầu.",vi:"Ví dụ minh họa"},{ja:"(3) ちょうど",romaji:"(3) chiょudo",vi:"今から"},{ja:"V ている",romaji:"V teiru",vi:"ところです"},{ja:"A: ピンポン",romaji:"A: ピンポン",vi:"しませんか。Cậu có chơi bóng bàn không?"},{ja:"B: 今",romaji:"B: 今",vi:"勉強しているところですから、あとで"},{ja:"A: 会議の資料は",romaji:"A: 会議no資料wa",vi:"もう"},{ja:"B: すみません。今",romaji:"B: sumimasen。今",vi:"コピーしているところですから、もう少し"},{ja:"A: ８時のバスは",romaji:"A: ８時noバスwa",vi:"もう"},{ja:"B: はい、たった今",romaji:"B: wai、taっta今",vi:"出たところです。Vâng, vừa m ới đi."},{ja:"良子さんは",romaji:"良子sanwa",vi:"たった今"},{ja:"A: けさ",romaji:"A: kesa",vi:"ハノイに"},{ja:"B: はい、たった今",romaji:"B: wai、taっta今",vi:"着いたところだ。Vâng, tôi vừa đến."},{ja:"田中さんは",romaji:"田中sanwa",vi:"FPT ビルで"},{ja:"・Không sử dụng với các động từ chỉ trạng thái kết quả như",romaji:"Không sử dụng với các động từ chỉ trạng thái kết quả như",vi:"結婚している、知っている…"},{ja:"ご飯を食べる",romaji:"go飯o食beru",vi:"（１）（２）（２）（２）（２）（２）（２）（２）（２） （３）"},{ja:"（１） ご飯を",romaji:"（１） go飯o",vi:"食べるところです。"},{ja:"（２） ご飯を",romaji:"（２） go飯o",vi:"食べているところです。"},{ja:"（３） ご飯を",romaji:"（３） go飯o",vi:"食べたところです。"},{ja:"山田さんと山本さんは",romaji:"山田santo山本sanwa",vi:"３か月まえに"},{ja:"田中さんは",romaji:"田中sanwa",vi:"３週間まえに"},{ja:"このカメラは",romaji:"konoカメラwa",vi:"きのう"},{ja:" Thể hiện quan hệ nhân quả với 「～ばかりですから、～」、「～ばかりなので、～」",romaji:" Thể hiện quan hệ nhân quả với ～bakaridesukara、～、～bakarinanode、～",vi:"Ví dụ minh họa"},{ja:"ペンキを",romaji:"ペンキo",vi:"塗ったばかりなので、触らないようにしてください。"},{ja:" Thể hiện quan hệ nghịch lý, không ngờ với 「～ばかりですなのに、～」",romaji:" Thể hiện quan hệ nghịch lý, không ngờ với ～bakaridesunanoni、～",vi:"Ví dụ minh họa"},{ja:"この時計は",romaji:"kono時計wa",vi:"買ったばかりなのに、もう壊れてしまいました。"},{ja:"「V たところ」 ＆ 「V たばかり」",romaji:"V tatokoro ＆ V tabakari",vi:"Ví dụ minh họa"},{ja:"「V たところ」",romaji:"V tatokoro",vi:"「V たばかり」"},{ja:"quá khứ nào khác ngoài 「たった今」",romaji:"quá khứ nào khác ngoài taっta今",vi:"khứ như「この間」「きょねん」…"},{ja:"飛行機は",romaji:"飛行機wa",vi:"もう"},{ja:"…ええ、たった今",romaji:"…ee、taっta今",vi:"着いたところです。"},{ja:"V たばかり cũng được coi như 1 danh từ",romaji:"V tabakari cũng được coi như 1 danh từ",vi:"FPT University Tiếng Nhật cơ sở 5"}]},{id:4580,lesson:47,level:"N4",title:"Thể thông thường + そうです。 (cách diễn đạt khi muốn truyền đạt thông tin",meaning:"(tôi) nghe nói là ~",usage:[" nghe nói)","3 và không có nhận định của bạn. Để nhấn mạnh thêm sự chắc chắn của thông tin, có thể","dẫn thêm nguồn gốc của thông tin đó với cụm từ 「～によると」","＊ Cách kết hợp:","Động từ V る･V ない･V た","Tính từ đuôi i dạng","～い・くない…","Tính từ đuôi na ngắn ～だ・ではない…","Danh từ ～だ・ではない…"],notes:["(1) Mẫu câu này khác cả về ý nghĩa và cách kết hợp so với mẫu câu 「そうです」 học ở bài 43","Xem ví dụ sau:","① 雨が 降りそうです。 Có vẻ như trời sắp mưa.","② 雨が 降るそうです。 Tôi nghe nói là trời sẽ mưa.","Ở câu ① nói về dự đoán, phán đoán dựa vào sự quan sát của của bản thân, còn câu thứ ②","đơn thuần chỉ là truyền đạt, kể lại sự việc, thông tin mình đã nghe được ở đâu đó và không có","nhận định của bản thân.","FPT University Tiếng Nhật cơ sở 5","(2) Mẫu câu này không kết hợp với các cách nói sau: thể ý chí（しよう）, cấm đoán（するな）,","mệnh lệnh（しろ）, suy đoán（するでしょう）, nhờ vả（してください、しないでください）.","Ngoài ra, các mẫu câu khác đều có thể kết hợp được với mẫu câu này.","（ × ）山本さんは アメリカへ 行こうそうです。","（ ○ ）山本さんは アメリカへ 行くつもりだそうです。","(3) Khi muốn thể hiện ý phủ định hay quá khứ với mẫu câu này, phần 「そうです」không thay","đổi, chỉ thay đổi thời của các động từ, danh từ, tính từ đi trước nó mà thôi.","（ × ）リーさんは 中国へ 帰るそうじゃありません。","（ ○ ）リーさんは 中国へ 帰らないそうです。","(4) Sự khác nhau giữa「～そうです」và「～と言っていました」","「～と言っていました」chỉ dùng khi truyền đạt những thông tin mà mình trực tiếp nghe được","từ người nói đó, còn 「～そうです」có thể dùng với trường hợp nghe từ những nguồn khác","(không nhất thiết phải đúng là người đó nói)","FPT University Tiếng Nhật cơ sở 5"],examples:[{ja:"① 天気予報によると、あしたは",romaji:"① 天気予報niyoruto、ashitawa",vi:"いい天気に"},{ja:"② 田中さんは",romaji:"② 田中sanwa",vi:"今年の１２月に"},{ja:"③ 東京は",romaji:"③ 東京wa",vi:"とても"},{ja:"④ 先生の話によると、彼女は",romaji:"④ 先生no話niyoruto、彼女wa",vi:"みんなの前で"},{ja:"⑤ ラオさんの電話によると、アリさんは",romaji:"⑤ ラオsanno電話niyoruto、アリsanwa",vi:"パスポートを"}]},{id:4581,lesson:47,level:"N4",title:"“Sentence” (cách thể hiện sự phán đoán, suy đoán",meaning:"Hình như là ～",usage:["ようです。 theo trực giác và không chắc chắn lắm)","Dạng thông thường","trên những cảm giác, cảm nhận (5 giác quan) của bản thân. Vì thế, những suy đoán đó có thể","không chính xác.","＊ Cách kết hợp:","Động từ V る･V ない･V た","Tính từ đuôi i dạng ～い・くない… ようです。","Tính từ đuôi na ngắn ～な・ではない…","Danh từ ～の・ではない…"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"“Sentence” (cách thể hiện sự phán đoán, suy đoán",romaji:"“Sentence” (cách thể hiện sự phán đoán, suy đoán",vi:"Hình như là ～"}]},{id:4582,lesson:48,level:"N4",title:"Bài 48 - Điểm ngữ pháp chính",meaning:"Bài 48 - Điểm ngữ pháp chính",usage:["「使役文」","Thể sai khiến","(Dạng động từ diễn đạt mệnh lệnh, yêu cầu)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 48 - Điểm ngữ pháp chính",romaji:"Bài 48 - Điểm ngữ pháp chính",vi:"Bài 48 - Điểm ngữ pháp chính"}]},{id:4583,lesson:48,level:"N4",title:"Cách chia động từ thể sai khiến (chia từ động từ dạng từ điển):",meaning:"cho (ai đó) làm ～; bắt (ai đó) làm ～",usage:["Nhóm I : chuyển đuôi 「u」sang a +せる","Thể từ điển Thể sai khiến","書く（かく） 書かせる","急ぐ（いそぐ） 急がせる","飲む（のむ） 飲ませる","呼ぶ（よぶ） 呼ばせる","作る（つくる） 作らせる","手伝う（てつだう） 手伝わせる","持つ（もつ） 持たせる","直す（なおす） 直させる","Nhóm I I : bỏ る thêm させる","Thể từ điển Thể sai khiến","食べる（たべる） 食べさせる","調べる（しらべる） 調べさせる","覚える（おぼえる） おぼえさせる","Nhóm I I I","Thể từ điển Thể sai khiến","する させる","来る（くる） 来させる（こさせる）","FPT University Tiếng Nhật cơ sở 5","2.1. Động từ thể sai khiến biểu hiện ý cho phép (cho làm gì) hay mệnh lệnh, yêu cầu, cưỡng","chế (bắt làm gì…). Do đây là mẫu câu thể hiện ý sai khiến, mệnh lệnh rất mạnh của người","trên yêu cầu người dưới làm gì đó và người dưới phải làm theo. Vì thế, không sử dụng mẫu","này đối với những quan hệ ngang bằng hay đối với người trên, thay vào đó sẽ dùng các","mẫu đã học về quan hệ cho nhận như: 「Ｖていただく（４１課）」、「Ｖてもらう（２","４課）」(tuy nhiên những động từ mang ý diễn đạt tâm lý, tình cảm như 「しんぱいする、","びっくりする、困る」thì vẫn có thể dùng với người trên với ý: làm cho lo lắng, làm cho","ngạc nhiên, làm cho khó khăn…)","2.2. Mẫu câu:","2.2.1. Trường hợp #1: đối với “tự động từ”（自動詞）","～を Ｖ（さ）せる","mang nghĩa sai khiến, mệnh lệnh yêu cầu ai đó làm gì. Trong phạm vi bài này dùng chủ yếu","い く かえ かよ しゅっちょう しゅっせき あそ","các tự động từ sau: 行く、来る、帰る、通う、 出 張 する、 出 席 する、遊ぶ. Trong kiểu câu","này, người thực hiện hành động, động tác sẽ đi với trợ từ 「を」。"," kiểu câu này còn được gọi tên là kiểu câu 「を-使役文」(câu sai khiến với trợ từ を)","mang nghĩa sai khiến, mệnh lệnh yêu cầu ai đó làm gì. Trong kiểu câu này, người thực hiện","hành động, động tác sẽ đi với trợ từ 「に」, còn tân ngữ (đối tượng tác động của động từ)","vẫn được xác định bởi trợ từ 「を」."," kiểu câu này còn được gọi tên là kiểu câu 「に-使役文」(câu sai khiến với trợ từ に)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"（１）部長は",romaji:"（１）部長wa",vi:"加藤さんを"},{ja:"（２） 私 は",romaji:"（２） 私 wa",vi:"娘を"},{ja:"2.2. Trường hợp #1: đối với “tha động từ”（他動詞）",romaji:"2.2. Trường hợp #1: đối với “tha động từ”（他動詞）",vi:"Ví dụ minh họa"},{ja:"（５）先生は",romaji:"（５）先生wa",vi:"生徒に"},{ja:"（６）朝は",romaji:"（６）朝wa",vi:"忙 しいですから、 娘 に"},{ja:"Tham khảo – M ở rộng: 1 số trường hợp đặc biệt dùng với「を」và「に」",romaji:"Tham khảo – M ở rộng: 1 số trường hợp đặc biệt dùng vớiovàni",vi:"Ví dụ minh họa"}]},{id:4584,lesson:48,level:"N4",title:"Trường hợp với chủ thể hành động của tha động từ + 「を」",meaning:"Trường hợp với chủ thể hành động của tha động từ + 「を」",usage:["Những động từ như 「待つ、勉強する」là tha động từ nhưng cũng có khi đi với trợ từ 「を」","わたしは 弟を 駅で 待たせた。","わたしは 弟に 父の帰りを 待たせた。","わたしは 娘を アメリカで 勉強させた。","わたしは 娘に ピアノを 勉強させた。"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Trường hợp với chủ thể hành động của tha động từ + 「を」",romaji:"Trường hợp với chủ thể hành động của tha động từ + o",vi:"Trường hợp với chủ thể hành động của tha động từ + 「を」"}]},{id:4585,lesson:48,level:"N4",title:"Trường hợp với chủ thể hành động của tự động từ + 「に」",meaning:"cho phép tôi (làm gì), hãy để tôi (làm gì) được không?",usage:["2.1. Trường hợp 1:","Những động từ như「行く、来る、帰る、歩く」là tự động từ nhưng cũng có khi đi với trợ từ","「に」để tránh lặp trợ từ 「を」","先生は 学生を 歩かせた。","先生は 学生に 山道を 歩かせた。","2.2. Trường hợp 2:","Những động từ như「答える、しゃべる、言う、質問する、反対する、発言する」là những tự","động từ thực hiện hành vi có hướng đến 1 đối tượng nào đó nhưng có nhiều khi dùng trợ từ","「に」thay cho trợ từ「を」","・彼に 答えさせた。","・山田くんに 言わせよう。","FPT University Tiếng Nhật cơ sở 5","2.2.3. (Cách nói xin phép làm","Ｖ（さ）せて いただけませんか。","gì một cách lịch sự)","được thực hiện 1 hành động nào đó","Cấu trúc mẫu câu:","Động từ 使役 chia dạng て いただけませんか。","（× いただきませんか）"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"すみませんが、早く",romaji:"sumimasenga、早ku",vi:"帰らせて"},{ja:"コピー機を",romaji:"コピー機o",vi:"使わせて"},{ja:"すみませんが、写真を",romaji:"sumimasenga、写真o",vi:"撮らせて"},{ja:"「Ｖ（さ）せて",romaji:"Ｖ（sa）sete",vi:"ください」"},{ja:"「Ｖ（さ）せて",romaji:"Ｖ（sa）sete",vi:"くださいませんか」"}]},{id:4586,lesson:48,level:"N4",title:"Kính ngữ:",meaning:"Kính ngữ:",usage:["Kính ngữ gồm 1 hệ thống các từ ngữ (danh từ, động từ, tính từ, trợ từ…), mẫu câu dùng để thể","hiện sự tôn trọng, kính trọng của người nói với người nghe hoặc người ở ngôi thứ ba (người được","nhắc tới trong hội thoại giữa người nói và người nghe). Về cơ bản, trong tiếng Nhật có nhiều","trường hợp dùng kính ngữ khác nhau và người nói thường bày tỏ sự kính trọng của mình với","người nghe (hoặc người được nhắc tới) tùy theo mối quan hệ giữa người nói với những người này.","Có ba mối quan hệ chính khi sử dụng kính ngữ:","Người nói là người ít tuổi hơn, cấp dưới hoặc là người có địa vị xã hội thấp hơn. Khi đó sẽ","sử dụng kính ngữ với với những người nhiều tuổi hơn, với cấp trên hoặc với người có địa vị","xã hội cao hơn mình.","Người nói không có quan hệ thân thiết với người nghe (ví dụ trong lần đầu tiên gặp gỡ).","Căn cứ vào mối quan hệ “trong” và “ngoài”: theo mối quan hệ này, người “trong” được","quan niệm là gồm những người cùng một gia đình, cùng công ty… Còn người “ngoài” là","những người không cùng nhóm nêu trên. Khi người nói nhắc đến một người trong nhóm","của mình với một người ngoài nhóm thì người được nói tới đó cũng được coi như ngang","hàng với chính người nói dù người này có địa vị xã hội cao hơn hay nhiều tuổi hơn. Vì thế,","trong trường hợp này người nói không cần dùng kính ngữ."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Kính ngữ:",romaji:"Kính ngữ:",vi:"Kính ngữ:"}]},{id:4587,lesson:48,level:"N4",title:"Các loại kính ngữ: Có 3 loại chính:",meaning:"Các loại kính ngữ: Có 3 loại chính:",usage:["Tôn kính ngữ「尊敬語（そんけいご）」: thể hiện sự tôn trọng, tôn kính, đề cao hành vi,","hành động của người nói (A) đối với người nghe (B) hoặc người được đề cập đến (C).","Tuyệt đối không sử dụng cho bản thân (A) hoặc người “trong” của (A) trong trường hợp","(B) là người “ngoài”.","Khiêm nhường ngữ「謙譲語（けんじょうご）」: thể hiện sự nhún nhường, khiêm tốn, hạ","thấp bản thân của (A) nhằm thể hiện sự kính trọng đối với (B) hoặc (C). Tuyệt đối không","sử dụng cho (B) hoặc (C) (trừ trường hợp đối với người “trong” như người trong gia","đình…)","Thể lịch sự「丁寧語（ていねいご）」: thể hiện sự lịch sự, lễ phép nên phạm vi sử dụng","khá rộng, có thể sử dụng với hầu hết các đối tượng","FPT University Tiếng Nhật cơ sở 5"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Các loại kính ngữ: Có 3 loại chính:",romaji:"Các loại kính ngữ: Có 3 loại chính:",vi:"Các loại kính ngữ: Có 3 loại chính:"}]},{id:4588,lesson:49,level:"N4",title:"Bài 49 - Điểm ngữ pháp chính",meaning:"Bài 49 - Điểm ngữ pháp chính",usage:["「尊敬語」","(TÔN KÍNH NGỮ)","Có nhiều cách để tạo TÔN KÍNH NGỮ:"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 49 - Điểm ngữ pháp chính",romaji:"Bài 49 - Điểm ngữ pháp chính",vi:"Bài 49 - Điểm ngữ pháp chính"}]},{id:4589,lesson:49,level:"N4",title:"Dùng tiền tố 「お」 và「 ご」(viết chữ Hán đều là 御 (NGỰ))",meaning:"Dùng tiền tố 「お」 và「 ご」(viết chữ Hán đều là 御 (NGỰ))",usage:["Tiền tố 「お」 và「 ご」được sử dụng rất nhiều trong câu kính ngữ. Chữ 御 (NGỰ)) với tư cách là","tiền tố được thêm vào phía trước các loại từ (danh từ, tính từ, phó từ ) và có 2 cách đọc, lúc là","「お」, lúc là「 ご」tùy theo loại từ nó ghép là từ thuần Nhật (Hòa ngữ - 和語) hay là từ gốc Hán","(Hán ngữ - 漢語).","Hòa ngữ (hay còn gọi là từ Nhật chế) là những từ gốc Nhật, từ vốn có của tiếng Nhật từ xưa, còn","Hán ngữ là những từ được lưu truyền từ Trung Quốc. (Thông thường cách nhận biết là Nhật ngữ là","những từ 1 chữ Hán, Hán ngữ là những từ gồm 2 chữ Hán)","V N A, Na","わ ご なお なら やす やさ","Từ thuần Nhật (和語) 直す、習う 休み 優しい","かんご しゅうり べんきょう きゅうけい しんせつ","Hán ngữ (漢語) 修理する、 勉 強 する 休憩 親切な","Về nguyên tắc, 「お」sẽ đi với những từ thuần Nhật và「ご」sẽ ghép với những từ gốc Hán. Tuy"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"như: お洗濯する、お掃除する、お邪魔する.",romaji:"như: o洗濯suru、o掃除suru、o邪魔suru.",vi:"Ví dụ minh họa"},{ja:"Danh từ: お宅、お国、お子さん、ご家族、ご質問、ご気分",romaji:"Danh từ: o宅、o国、o子san、go家族、go質問、go気分",vi:"Ví dụ minh họa"},{ja:"Tính từ: お忙しい、お元気、お上手",romaji:"Tính từ: o忙shii、o元気、o上手",vi:"Ví dụ minh họa"},{ja:"Phó từ: ごゆっくり、ごいっしょに、お大事に",romaji:"Phó từ: goyuっkuri、goiっshiょni、o大事ni",vi:"FPT University Tiếng Nhật cơ sở 5"}]},{id:4590,lesson:49,level:"N4",title:"Sử dụng động từ THỂ BỊ ĐỘNG:",meaning:"thể hiện sự kính trọng",usage:["Ｖ（ら）れます","từ dạng bị động. Hầu hết tất cả các động từ đều có thể áp dụng được trừ động từ dạng","khả năng (可能形) và một số động từ như: できます、わかります、いります","Cả nam và nữ đều sử dụng được nhưng nam giới thường sử dụng nhiều hơn. Ngoài ra,","kiểu thể hiện này cũng hay được dùng trong văn viết."],notes:["＊ Chú ý: Tôn kính ngữ không sử dụng khi nói về hành động của người nói nên đối với câu hỏi","sử dụng tôn kính ngữ thì khi trả lời không sử dụng tôn kính ngữ với hành động của mình.","A: いつ お国へ 帰られますか。Khi nào bạn về nước?","B: あさって 帰ります。 Ngày kia tôi về.","( あさって 帰られます。（×）)"],examples:[{ja:"社長 は",romaji:"社長 wa",vi:"さっき"},{ja:"お酒を",romaji:"o酒o",vi:"やめられたんですか。"},{ja:"会長 は",romaji:"会長 wa",vi:"今"}]},{id:4591,lesson:49,level:"N4",title:"Biến đổi động từ dạng -MASU",meaning:"thể hiện sự tôn kính, kính trọng (mức độ cao nhất)",usage:["おＶます になります","sử dụng động từ dạng bị động. Cả nam và nữ đều dùng được nhưng nữ giới","thường sử dụng nhiều hơn.","Không áp dụng với động từ nhóm 3 và động từ 1 âm tiết như: 見ます、寝ま","す、います…","FPT University Tiếng Nhật cơ sở 5"],notes:["＊ Chú ý: Tôn kính ngữ không sử dụng khi nói về hành động của người nói nên đối với câu hỏi","sử dụng tôn kính ngữ thì khi trả lời không sử dụng tôn kính ngữ với hành động của mình.","こんばん なん じ やまもと あ","A: 今晩 何時に 山本さんに お会いに なりますか。Tối nay mấy giờ ngài sẽ gặp chị Yamamoto?","B: ６時１５分過ぎに 会います。 Tôi sẽ gặp lúc 6 giờ 15","( ６時１５分過ぎに お会いになります。（×）)","FPT University Tiếng Nhật cơ sở 5","4．Tôn kính ngữ đặc biệt:","Bảng KÍNH NGỮ ĐẶC BIỆT của động từ","(Tôn kính ngữ và Khiêm nhường ngữ)","Tôn kính ngữ Khiêm nhường ngữ","いきます いらっしゃいます","きます *おいでに なります","います *みえます（tôn kính ngữ của 来ます） おります","（V ています） （V ていらっしゃいます） （V ております）","たべます めしあがります いただきます","のみます *あがります","します なさいます いたします","（せつめい）します ご（せつめい）なさいます ご（せつめい）いたします／","いいます おっしゃいます もうします","しっています ごぞんじです ぞんじております","（そんじません）","～とおもいます *～とぞんじます","ねます おやすみになります","ききます うかがいます","Na／N です Na／N でいらっしゃいます","着ます *おめしになります","みます ごらんになります はいけんします","（V て）くれます （V て）くださいます","（V て）あげます *（V て）さしあげます","もらいます いただきます","（V て）もらいます ちょうだいします","（V て）いただきます","みせます おめにかけます","あいます おめにかかります","Trong giáo trình này không đề cập đến nhưng được sử dụng nhiều","FPT University Tiếng Nhật cơ sở 5","5．Tôn kính ngữ của Danh từ & Tính từ:","5.1. Tôn kính ngữ của Danh từ:","Ở cấp độ đơn vị danh từ, ngoài những kính ngữ đặc biệt đã liệt kê ở trên, có thể dung tiếp đầu ngữ","「お」và「ご」 để tạo thành kính ngữ. Tuy nhiên, cũng có danh từ không thể ghép 「お」hay"],examples:[{ja:"社長 は",romaji:"社長 wa",vi:"お帰りに"},{ja:"新聞を",romaji:"新聞o",vi:"お読みに"},{ja:"ぶ ちょう",romaji:"bu chiょu",vi:"か とう"},{ja:"部長は",romaji:"部長wa",vi:"加藤さんを"},{ja:"（こどもの",romaji:"（kodomono",vi:"ばあい）"},{ja:"（～さま）",romaji:"（～sama）",vi:"Giải thích:"}]},{id:4592,lesson:49,level:"N4",title:"Một số danh từ chỉ chức danh như 部長、先生、社長…bản thân nó đã bao hàm ý tôn kính nên",meaning:"Một số danh từ chỉ chức danh như 部長、先生、社長…bản thân nó đã bao hàm ý tôn kính nên",usage:["không cần thêm「さん」 ×先生さん (khác với tiếng Hàn Quốc)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Một số danh từ chỉ chức danh như 部長、先生、社長…bản thân nó đã bao hàm ý tôn kính nên",romaji:"Một số danh từ chỉ chức danh như 部長、先生、社長…bản thân nó đã bao hàm ý tôn kính nên",vi:"Một số danh từ chỉ chức danh như 部長、先生、社長…bản thân nó đã bao hàm ý tôn kính nên"}]},{id:4593,lesson:49,level:"N4",title:"Với những danh từ chưa bao hàm ý kính trọng thì có thể thêm 「さん（さま）」để tăng thêm",meaning:"Với những danh từ chưa bao hàm ý kính trọng thì có thể thêm 「さん（さま）」để tăng thêm",usage:["ý lịch sự","客→お客さん（さま） 二人→お二人さん（さま）","医者→お医者さん（さま） 花屋→（お）花屋さん"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Với những danh từ chưa bao hàm ý kính trọng thì có thể thêm 「さん（さま）」để tăng thêm",romaji:"Với những danh từ chưa bao hàm ý kính trọng thì có thể thêm san（sama）để tăng thêm",vi:"Với những danh từ chưa bao hàm ý kính trọng thì có thể thêm 「さん（さま）」để tăng thêm"}]},{id:4594,lesson:49,level:"N4",title:"Điều đặc biệt cần chú ý đó là các trường hợp nói chuyện về người trên thuộc quan hệ trong với",meaning:"Điều đặc biệt cần chú ý đó là các trường hợp nói chuyện về người trên thuộc quan hệ trong với",usage:["người thuộc quan hệ ngoài. Nếu chỉ suy xét về quan hệ trên dưới thì tương đối dễ vì chỉ việc","FPT University Tiếng Nhật cơ sở 5","dùng các từ kính ngữ đối với người trên nhưng trong đó nếu xem xét thêm về mối quan hệ"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Cũng giống như Danh từ, có thể thêm tiền tố 「お」và「ご」để tạo thành kính ngữ. Tuy nhiên,",romaji:"Cũng giống như Danh từ, có thể thêm tiền tố ovàgođể tạo thành kính ngữ. Tuy nhiên,",vi:"Ví dụ minh họa"},{ja:"cũng có trường hợp không dùng được. Vd: ×おいい ×おおいしい",romaji:"cũng có trường hợp không dùng được. Vd: ×oii ×ooishii",vi:"Ví dụ minh họa"},{ja:"A-い／A-な",romaji:"A-i／A-na",vi:"副詞 (Phó từ)"},{ja:"じょうず（な）",romaji:"jiょuzu（na）",vi:"→"},{ja:"げんき（な）",romaji:"genki（na）",vi:"→"},{ja:"ひま（な）",romaji:"hima（na）",vi:"→"},{ja:"ていねい（な）",romaji:"teinei（na）",vi:"→"},{ja:"しんせつ（な）",romaji:"shinsetsu（na）",vi:"→"},{ja:"(1)",romaji:"(1)",vi:"おＶです"},{ja:"・お呼びです",romaji:"o呼bidesu",vi:"="},{ja:"・お見えです",romaji:"o見edesu",vi:"="},{ja:"・おいでです",romaji:"oidedesu",vi:"="},{ja:"・お急ぎですか",romaji:"o急gidesuka",vi:"Ví dụ minh họa"},{ja:"・お帰りですよ",romaji:"o帰ridesuyo",vi:"Ví dụ minh họa"},{ja:"(2)",romaji:"(2)",vi:"おＶますください"},{ja:"・待ってください",romaji:"待っtekudasai",vi:"="},{ja:"・入ってください",romaji:"入っtekudasai",vi:"="},{ja:"・座ってください",romaji:"座っtekudasai",vi:"="}]},{id:4595,lesson:50,level:"N4",title:"Bài 50 - Điểm ngữ pháp chính",meaning:"Bài 50 - Điểm ngữ pháp chính",usage:["「 謙 譲 語」","(KHIÊM NHƯỜNG NGỮ)","Khiêm nhường ngữ là cách nói khiêm tốn, nhún nhường dùng cho những hành động, hành vi của","người nói A hay những người thuộc quan hệ trong của A đối với người nghe B hay người được nói tới","C. Chính vì vậy, cách nói này tuyệt đối không được sử dụng đối với những hành vi của người thuộc","quan hệ ngoài, với người B hay C."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 50 - Điểm ngữ pháp chính",romaji:"Bài 50 - Điểm ngữ pháp chính",vi:"Bài 50 - Điểm ngữ pháp chính"}]},{id:4596,lesson:50,level:"N4",title:"おＶします khiêm nhường ngữ của động từ",meaning:"thể hiện sự nhún nhường, hạ mình của người nói",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:[" Chú ý:"," Mẫu câu này được sử dụng khi người nói thực hiện hành động gì đó cho người nghe","hay người được nhắc tới nên sẽ không dùng với trường hợp mà hành động của người","nói không liên quan đến người nghe, người được nhắc tới. (quy tắc này giống với","trường hợp các mẫu câu về quan hệ cho nhận học ở bài 24 và 41)","わたし まいにち しんぶん よ よ","(1) 私 は 毎日 新聞を 読みます。 （×）お読みします","(2) A：いつ おくにへ おかえりに なりますか。","B: らいしゅう かえります。（×）おかえりします","Hàng ngày tôi đọc báo."," Không dùng trong trường hợp người được nhắc tới trong câu chuyện là người thuộc","nhóm mình kể cả người bề trên","FPT University Tiếng Nhật cơ sở 5","ちち えき おく","父を 駅まで お送りしました。（×）","父を 駅まで 送りました。（○）"," Không sử dụng những động từ có 1 âm tiết ví dụ như: 来ます、見ます、います","来ます → ×おきします ○まいります","見ます → ×おみします ○はいけんします","います → ×おいします ○おります"],examples:[{ja:"Nhóm I:",romaji:"Nhóm I:",vi:"持ちます"},{ja:"Nhóm II:",romaji:"Nhóm II:",vi:"調べます"},{ja:"Nhóm III:",romaji:"Nhóm III:",vi:"案内します"},{ja:"邪魔します",romaji:"邪魔shimasu",vi:"お邪魔します"}]},{id:4597,lesson:50,level:"N4",title:"ご N します Khiêm nhường ngữ của",meaning:"ご N します Khiêm nhường ngữ của",usage:["danh động từ"," Cách ghép: Cách danh động từ (động từ nhóm 3 có dạng「N します」thường là những từ","gốc Hán nên sẽ ghép 「ご」và tạo thành 「ご N します」. (nhưng không áp dụng với các","động từ như 「勉強します、実習します、結婚します」)"],notes:["một số trường hợp đặc biệt","でんわ でんわ やくそく やくそく","電話します  お電話します 約束 します  お 約束 します"],examples:[{ja:"江戸東京博物館へ",romaji:"江戸東京博物館e",vi:"ご案内します。"},{ja:"今日の",romaji:"今日no",vi:"予定を"}]},{id:4598,lesson:50,level:"N4",title:"Động từ khiêm nhường ngữ đặc biệt: (xem BẢNG KÍNH NGỮ ĐẶC BIỆT của động từ)",meaning:"Động từ khiêm nhường ngữ đặc biệt: (xem BẢNG KÍNH NGỮ ĐẶC BIỆT của động từ)",usage:["FPT University Tiếng Nhật cơ sở 5"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Động từ khiêm nhường ngữ đặc biệt: (xem BẢNG KÍNH NGỮ ĐẶC BIỆT của động từ)",romaji:"Động từ khiêm nhường ngữ đặc biệt: (xem BẢNG KÍNH NGỮ ĐẶC BIỆT của động từ)",vi:"Động từ khiêm nhường ngữ đặc biệt: (xem BẢNG KÍNH NGỮ ĐẶC BIỆT của động từ)"}]},{id:4599,lesson:50,level:"N4",title:"Thể lịch sự",meaning:"Thể lịch sự",usage:[" Các thể lịch sự hay dùng:","＊ ございます","電話は 階段の 横に ございます。","Điện thoại có ở bên cạnh cầu thang ạ.","＊ ～で ございます","はい、IMC で ございます。","Vâng, IMC xin nghe.","でんき し ゅ っ み と み ら ねが","…パワー電気の シュッミトですが、ミラーさん、お願いします。","Tôi là Summit người của công ty điện lực Power, tôi xin gặp anh Miler.","＊ よろしいでしょうか","お飲み物は 何が よろしいでしょうか。","Ngài sẽ dùng đồ uống gì ạ?","・・・ こ ひ ねが","… コーヒーを お願いします。","Cho tôi cà phê."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Thể lịch sự",romaji:"Thể lịch sự",vi:"Thể lịch sự"}]}];export{n as GRAMMAR_N4};
